"""
Unified Standalone Urdu & Code-Mixed G2P Pipeline (All-In-One Single File).
Zero Hardcoded Dictionaries in Engine Code. Zero Static Lexicons. Zero Word Equality Checks.

Combines:
1. General American English Loanword G2P & Generative Morphological Transducers.
2. Classical Perso-Arabic Graphotactic Rules Engine (v5).
3. Generative Noun Phrase Chunking LID (Language Identification).
4. Curated 2,500 Base Tier Dictionary Loader.

Public API:
    convert(text: str, mode: str = "standard") -> str
    word_to_ipa(word: str, mode: str = "standard") -> str
    english_ipa(word: str) -> str
    english_score(word: str) -> float

CLI Usage:
    python pipeline.py "اقوام متحدہ اور مصنوعی ذہانت کے نئے ماڈلز"
"""

