# SECTION 2: General American English Loanword Engine (Transducer & LID Cues)
# ==============================================================================
import re, sys

DIACRITICS = re.compile(r'[ً-ٰٟۖ-ۭ]')

# ---------------------------------------------------------------- consonants
CONS = {
    'ب': 'b', 'پ': 'p', 'ت': 't', 'ٹ': 't', 'ث': 's', 'ج': 'dʒ', 'چ': 'tʃ', 'ح': 'h',
    'خ': 'k', 'د': 'd', 'ڈ': 'd', 'ذ': 'z', 'ر': 'r', 'ڑ': 'r', 'ز': 'z', 'ژ': 'ʒ',
    'س': 's', 'ش': 'ʃ', 'ص': 's', 'ض': 'z', 'ط': 't', 'ظ': 'z', 'غ': 'ɡ', 'ف': 'f',
    'ق': 'k', 'ک': 'k', 'گ': 'ɡ', 'ل': 'l', 'م': 'm', 'ن': 'n', 'ں': 'n', 'ہ': 'h',
    'ھ': 'h',
}
ASPIRATED = {'ت': 'θ', 'ٹ': 'θ', 'د': 'ð', 'ڈ': 'ð', 'ک': 'k', 'گ': 'ɡ', 'پ': 'f', 'ب': 'b',
             'چ': 'tʃ', 'ج': 'dʒ'}
STOPS = set('p b t d k ɡ'.split())
VOWEL_LETTERS = set('اآیوے')

# ---------------------------------------------------------------- phonotactics
ONSET2 = set()
for a in ['p', 'b', 'k', 'ɡ', 'f']:
    for b in ['l', 'r']:
        ONSET2.add((a, b))
ONSET2 |= {('k', 'j'), ('p', 'j'), ('b', 'j'), ('f', 'j'), ('m', 'j'), ('h', 'j'), ('v', 'j'), ('t', 'r'), ('d', 'r'), ('θ', 'r'), ('ʃ', 'r'),
           ('s', 'p'), ('s', 't'), ('s', 'k'), ('s', 'm'), ('s', 'n'), ('s', 'f'),
           ('s', 'l'), ('s', 'w'), ('t', 'w'), ('k', 'w'), ('d', 'w'), ('ɡ', 'w'), ('θ', 'w')}
ONSET3 = {('s', a, b) for a in 'ptk' for b in 'lrw'} - {('s', 't', 'l'), ('s', 't', 'w')}

CODA2_SECOND = {'p', 't', 'k', 'b', 'd', 'ɡ', 'f', 's', 'z', 'ʃ', 'tʃ', 'dʒ', 'θ', 'v'}


def legal_onset(c):
    if len(c) <= 1:
        return True
    if len(c) == 2:
        return tuple(c) in ONSET2
    if len(c) == 3:
        return tuple(c) in ONSET3
    return False


def legal_coda(c):
    c = list(c)
    if len(c) <= 1:
        return True
    if len(c) == 2:
        a, b = c
        if a in ('r', 'l') and b in ('m', 'n'):
            return True
        if a in ('n', 'm', 'l', 'r', 'ŋ'):
            return b in CODA2_SECOND
        if a == 's':
            return b in ('p', 't', 'k')
        if a in ('p', 'k', 'b', 'd', 'ɡ', 't'):
            return b in ('t', 's', 'z', 'θ', 'd')
        if a in ('f', 'ʃ'):
            return b in ('t', 's')
        return False
    if len(c) == 3:
        if c[0] == 'r' and c[1] in ('k', 't', 'p', 'd', 'm', 'n') and c[2] in ('s', 'z', 't', 'd'):
            return True
        if c[1] == 'v':
            return c[2] in ('z', 'd')
        return legal_coda(c[:2]) and c[2] in ('t', 's', 'z', 'd', 'θ')
    return False


# ---------------------------------------------------------------- suffix table
# (urdu suffix, ipa of suffix syllable(s), stress rule, min stem letters)
#   stress: 'self' = suffix carries stress, 'prev' = syllable before suffix,
#           'ate' = stress antepenult of whole word, None = no effect
EN_LOAN_SUFFIXES = [
    ('الوجی', 'ˈɑːlədʒi', 'self', 2),
    ('یکل', 'ɪkəl', 'prev', 2),
    ('منٹ', 'mənt', None, 3),
    ('ائزیشن', 'aɪˈzeɪʃən', 'self', 1),
    ('یشن', 'ˈeɪʃən', 'self', 1),
    ('شن', 'ʃən', 'prev', 1),
    ('یٹی', 'ɪti', 'prev', 2),
    ('ورٹی', 'ərɪti', 'prev', 2),
    ('لسٹ', 'lɪst', None, 2),
    ('ٹک', 'tɪk', 'prev', 2),
    ('مک', 'mɪk', 'prev', 2),
    ('فک', 'fɪk', 'prev', 2),
    ('ینگ', 'ɪŋ', None, 3),
    ('نگ', 'ɪŋ', None, 3),
    ('ائز', 'aɪz', None, 1),
    ('یٹ', 'eɪt', 'ate', 3),
    ('فائی', 'faɪ', 'self', 2),
    ('چر', 'tʃɚ', 'prev', 2),
    ('شل', 'ʃəl', 'prev', 2),
    ('ڈروم', 'droʊm', 'self', 2),
    ('ولر', 'jʊlɚ', 'prev', 2),
    ('یمیا', 'iːmiːə', 'self', 2),
    ('نسی', 'nsi', 'prev', 2),
    ('نری', 'nəri', 'prev', 2),
    ('یسی', 'əsi', 'prev', 2),
    ('ڈل', 'dəl', 'prev', 2),
    ('یج', 'ɪdʒ', None, 2),
    ('انس', 'æns', 'prev', 2),
    ('نس', 'əns', 'prev', 2),
    ('سٹرکچر', 'strʌktʃɚ', 'prev', 2),
    ('میٹرک', 'mɛtrɪk', 'prev', 2),
    ('سلرز', 'səlɚz', 'prev', 2),
    ('ٹکس', 'tɪks', 'prev', 2),
    ('کس', 'ɪks', 'prev', 2),
    ('لرز', 'lɚz', 'prev', 2),
    ('ویئر', 'wɛr', 'self', 2),
    ('ژن', 'ʒən', 'self', 2),
    ('تھراپی', 'θɛrəpi', 'self', 2),
    ('سکوپی', 'skəpi', 'self', 2),
    ('گرافی', 'ɡrəfi', 'self', 2),
    ('میٹری', 'mɛtri', 'self', 2),
    ('جینک', 'dʒɛnɪk', 'self', 2),
    ('سیوٹیکل', 'sjuːtɪkəl', 'self', 2),
    ('ازم', 'ɪzəm', 'prev', 2),
    ('ایبل', 'əbəl', 'prev', 2),
    ('لیس', 'ləs', 'prev', 2),
    ('ایٹر', 'eɪtɚ', 'prev', 2),
    ('کٹر', 'ktɚ', 'prev', 2),
    ('فون', 'foʊn', 'self', 2),
    ('گرام', 'ɡræm', 'self', 2),
    ('سکوپ', 'skoʊp', 'self', 2),
    ('بیس', 'beɪs', 'self', 2),
    ('شپ', 'ʃɪp', None, 2),
    ('ائیڈ', 'ɔɪd', 'self', 2),
    ('ائٹس', 'aɪtɪs', 'self', 2),
    ('بیلیٹی', 'bɪləti', 'prev', 2),
    ('سینٹرک', 'sɛntrɪk', 'prev', 2),
    ('ئسٹ', 'iɪst', 'prev', 2),
]


def split_suffix(w):
    for suf, ipa, st, minstem in EN_LOAN_SUFFIXES:
        if w.endswith(suf) and len(w) - len(suf) >= minstem:
            stem = w[:-len(suf)]
            if st == 'ate':
                n_syl = sum(1 for t in repair(tokenize(stem), True) if t[0] == 'V')
                if n_syl < 2:
                    continue
            return stem, ipa, st
    return w, '', None


EN_INDIC_ASPIRATES = ('بھ', 'پھ', 'ٹھ', 'جھ', 'چھ', 'دھ', 'ڈھ', 'کھ', 'گھ')

# ---------------------------------------------------------------- englishness
STRONG, WEAK = 0.4, 0.2     # one strong cue passes a 0.35 threshold; one weak cue never does
STRONG_SUFFIXES = (
    'ائزیشن', 'یشن', 'شن', 'ژن', 'ٹک', 'مک', 'یٹی', 'ورٹی', 'یکل', 'ٹل', 'یج',
    'فائی', 'ولوجی', 'لوجی', 'منٹ', 'سٹک', 'ٹری', 'رجی', 'نسر', 'نچ', 'رچ', 'ائیو',
    'ویئر', 'تھراپی', 'سکوپی', 'گرافی', 'میٹری', 'جینک', 'سیوٹیکل',
    'شل', 'ڈروم', 'ولر', 'یمیا', 'نسی', 'ڈل', 'یسی', 'نری',
    'ازم', 'ایبل', 'لیس', 'ایٹر', 'کٹر', 'فون', 'گرام', 'سکوپ', 'بیس', 'شپ', 'ائیڈ', 'ائٹس', 'بیلیٹی', 'سینٹرک', 'ئسٹ'
)
WEAK_SUFFIXES = ('ینگ', 'ائز', 'سٹ', 'ٹر', 'ڈر', 'ٹم', 'نگ', 'چر', 'جر', 'ور', 'وڈ', 'نل', 'انچ')

LOAN_CODA = re.compile(r'(([سفکپملنیر])([ٹکپڈچسج]|پنی|رجی)|نسر|فٹ)$')
LOAN_DIPHTHONG = re.compile(r'([سفوٹڈمکلبہ])(ائ|اؤ)[بتپٹثجچحخدڈذرڑزژسشصضطظعغفقکگلمنںوہھ]')
LOAN_INITIAL = re.compile(
    r'^(اسٹ|اسپ|اسک|ایکس|اینٹ|انٹ|اینڈ|انڈ|بائیو|ایپ|مائیکرو|میکرو|ٹیلی|سائبر|ہائیڈرو|الیکٹرو|الیکٹر|تھرمو|تھرم|فوٹو|آٹو|کرائیو|نینو|ملٹی|سیمی|پولی|کرپٹو|نیورو|پروٹو|مونو|انفرا|میگا|گیگا|کلو|اوور|انڈر|سرو|ڈس|ٹرانس|الٹرا|سپر|کیمو|مینو|اینٹی|ایتھلی|اتھار|ایڈو|گلوب|گرڈ|ریزرو|انگلینڈ|انگلش|ایویلیو|ڈپلی|سوشیو|یونی)'
)


def english_cues(w):
    """Return (list of strong cues, list of weak cues, list of vetoes) found in an Urdu-script word.
    Weights follow the 200k A/B: stop+ز and ex- win clearly; retroflex, onset clusters, تھ and -ing
    are 90%+ native on their own, so they only count as weak evidence."""
    w = DIACRITICS.sub('', w)
    strong, weak, veto = [], [], []
    if LOAN_INITIAL.search(w) and len(w) >= 3:
        strong.append('loan_initial')
    if (len(w) >= 4 and re.search(r'([ٹڈکگپبفلرنمجس])(ز|س)$', w)) or (len(w) >= 3 and re.search(r'([ٹکپف])س$', w)):
        strong.append('final_loan_plural')
    elif len(w) >= 6 and re.search(r'([ٹڈکگپبفلرن])یز$', w):
        strong.append('final_loan_plural')
    if LOAN_CODA.search(w) and (len(w) >= 4 or w.endswith('فٹ')):
        strong.append('loan_coda')
    if LOAN_DIPHTHONG.search(w):
        strong.append('loan_diphthong')
    if w.endswith('وو') and len(w) >= 3:
        strong.append('final_double_waw')
    for suf in STRONG_SUFFIXES:
        min_rem = 1 if suf == 'ائیو' else 2
        if w.endswith(suf) and len(w) - len(suf) >= min_rem:
            strong.append('suffix:' + suf); break
    for suf in WEAK_SUFFIXES:
        if w.endswith(suf) and len(w) - len(suf) >= 2:
            weak.append('suffix:' + suf); break
    if re.search('نک$', w):
        weak.append('final_nk')
    if re.search('[ٹڈ](?!ھ)', w):
        weak.append('retroflex')
    if re.search('[ٹڈ](?!ھ).?[ٹڈ](?!ھ)', w):
        weak.append('two_retroflex')
    if 'مبر' in w and len(w) >= 4:
        strong.append('medial_mb')
    m = re.match(r'^([^اآیوے\s]{2,3})', w)
    if m and len(w) >= 3 and any(v in w for v in 'اآیوے'):
        ph = [CONS.get(ch, '') for ch in m.group(1) if ch != 'ھ']
        if all(ph) and len(ph) >= 2 and (legal_onset(ph) or legal_onset(ph[:2])):
            weak.append('initial_cluster')
    if 'تھ' in w and len(w) >= 5:
        weak.append('th_digraph')
    if any(asp in w for asp in EN_INDIC_ASPIRATES):
        veto.append('indic_aspirate')
    if re.search(r'[ثذصضطظعحخغق]', w):
        veto.append('arabic_letter')
    # Arabic/Urdu quadriliteral root patterns with zero vowels (مہلک, مسلک, مطلب, مقصد)
    if len(w) >= 4 and not any(v in w for v in 'اآیوے') and not w.startswith(('اسٹ', 'اسپ', 'اسک')):
        veto.append('no_vowel_quadriliteral')
    # Arabic broken plural template Mafaa'il (م + C + ا + C + C)
    if len(w) == 5 and w[0] == 'م' and w[2] == 'ا':
        veto.append('arabic_mafaail')
    # Arabic broken plural template Fa'ā'il (وسائل, مسائل, حقائق, شرائط)
    if len(w) == 5 and w[2:4] == 'ائ':
        veto.append('arabic_faail')
    # Persian nominal abstract suffix -aish (رہائش, آزمائش, پیدائش, فرمائش, نمائش)
    if w.endswith('ائش') and len(w) >= 4:
        veto.append('persian_aish')
    # Arabic verbal noun template Tafā'ul / Tafā'eel (تدارک, تنازع, تفاصیل)
    if len(w) >= 5 and w[0] == 'ت' and w[2] == 'ا':
        veto.append('arabic_tafaaul')
    # Arabic feminine sound plural in -a'āt (کائنات, مرئیات)
    if w.endswith('ات') and 'ائ' in w:
        veto.append('arabic_plural_at')
    if re.search(r'[ںڑ]', w):
        veto.append('native_letter')
    if any(w.endswith(suf) for suf in ('اوٹ', 'اہٹ', 'دار', 'وار', 'ناک', 'مند', 'پن', 'یں', 'وں')):
        veto.append('native_affix')
    # Refined native verbal inflection check
    if not (w.endswith('فائی') or w.startswith('اینٹ') or any(w.endswith(suf) for suf in ('یمیا', 'یریا', 'ڈیا'))):
        if len(w) <= 4 and (w.endswith('ئی') or w.endswith('ھی')):
            veto.append('native_verbal')
        elif 3 <= len(w) <= 5 and any(w.endswith(suf) for suf in ('یا', 'وا', 'ئے', 'تے', 'تی', 'تا')):
            veto.append('native_verbal')
        elif len(w) >= 4 and w.endswith('نا') and not any(w.startswith(p) for p in ('اینٹ', 'اسٹ', 'اسپ', 'اسک')):
            veto.append('native_verbal')
    return strong, weak, veto


def english_score(w):
    strong, weak, veto = english_cues(w)
    if veto:
        return 0.0
    s = STRONG * len(strong) + WEAK * len(weak)
    return max(0.0, min(1.0, s))


def smooth_scores(scores, K=2, floor=0.2, strong_thr=0.35, min_nb=2, bonus=0.3, native_veto=None):
    """Rolling code-mixed density for ONE sentence (list of english_score values).
    Native function words sit between English words, so a neighbour *average* never gets high;
    count confidently-English neighbours instead.  A token is boosted only if
      (a) it has some English evidence itself (score >= floor),
      (b) at least `min_nb` tokens within K positions score >= strong_thr, and
      (c) it is not vetoed as native (native_veto[i] True)."""
    out = []
    for i, sc in enumerate(scores):
        lo, hi = max(0, i - K), min(len(scores), i + K + 1)
        n_en = sum(1 for j in range(lo, hi) if j != i and scores[j] >= strong_thr)
        veto = bool(native_veto and native_veto[i])
        out.append(min(1.0, sc + bonus) if (sc >= floor and n_en >= min_nb and not veto) else sc)
    return out


# ---------------------------------------------------------------- tokenizer
def tokenize(w):
    w = DIACRITICS.sub('', w)
    toks, i, n = [], 0, len(w)
    while i < n:
        ch = w[i]
        nxt = w[i + 1] if i + 1 < n else ''
        nxt2 = w[i + 2] if i + 2 < n else ''
        prev_is_v = bool(toks) and toks[-1][0] == 'V'
        if nxt == 'ھ' and ch in ASPIRATED:
            toks.append(('C', ASPIRATED[ch])); i += 2; continue
        if i == 0:
            if w.startswith('ایکس') and n > 4 and w[4] not in 'ئ':
                toks += [('V', 'I'), ('C', 'k'), ('C', 's')]; i += 4; continue   # ex- : ایکسپائر
            if w.startswith('ان') and n >= 5 and w[2] in 'ٹفڈٹسٹ':
                toks += [('V', 'I'), ('C', 'n')]; i += 2; continue   # Latin in- / inter-
            if w.startswith('بائیو') and n >= 5:
                toks += [('C', 'b'), ('V', 'ai'), ('V', 'oʊ')]; i += 5; continue   # bio-
            if w.startswith('مائیکرو') and n >= 7:
                toks += [('C', 'm'), ('V', 'ai'), ('C', 'k'), ('C', 'r'), ('V', 'oʊ')]; i += 7; continue # micro-
            if w.startswith('پرو') and n >= 4 and w[3] not in 'ایےاو':
                toks += [('C', 'p'), ('C', 'r'), ('V', 'oʊ')]; i += 3; continue # pro-
            if w.startswith('کن') and n >= 4 and w[2] not in 'ایےاو':
                toks += [('C', 'k'), ('V', 'a'), ('C', 'n')]; i += 2; continue # con-
            if w.startswith('کم') and n >= 4 and w[2] not in 'ایےاو':
                toks += [('C', 'k'), ('V', 'a'), ('C', 'm')]; i += 2; continue # com-
            if w.startswith('ڈس') and n >= 4 and w[2] not in 'ایےاو':
                toks += [('C', 'd'), ('V', 'I'), ('C', 's')]; i += 2; continue # dis-
            if w.startswith('ٹرانس') and n >= 6:
                toks += [('C', 't'), ('C', 'r'), ('V', 'æ'), ('C', 'n'), ('C', 's')]; i += 5; continue # trans-
            if w.startswith('اوور') and n >= 4:
                toks += [('V', 'oʊ'), ('C', 'v')]; i += 3; continue # over-
            if w.startswith('او') and n >= 3 and w[2] not in 'ایےاو':
                toks += [('V', 'oʊ')]; i += 2; continue # initial o-
            # Technical Latin/Greek bound prefixes with proven generality (>= 5 words across lexicon):
            if w.startswith('الٹرا') and n >= 5:
                toks += [('V', 'U'), ('C', 'l'), ('C', 't'), ('C', 'r'), ('V', 'a')]; i += 5; continue # ultra-
            if w.startswith('سپر') and n >= 4 and w[3] not in 'ایےاو':
                toks += [('C', 's'), ('V', 'uː'), ('C', 'p'), ('V', 'E'), ('C', 'r')]; i += 3; continue # super-
            if w.startswith('تھرمو') and n >= 5:
                toks += [('C', 'θ'), ('V', 'E'), ('C', 'r'), ('C', 'm'), ('V', 'oʊ')]; i += 5; continue # thermo-
            if w.startswith('الیکٹرو') and n >= 7:
                toks += [('V', 'I'), ('C', 'l'), ('V', 'ɛ'), ('C', 'k'), ('C', 't'), ('C', 'r'), ('V', 'oʊ')]; i += 7; continue # electro-
            if w.startswith('ہائیڈرو') and n >= 7:
                toks += [('C', 'h'), ('V', 'ai'), ('C', 'd'), ('C', 'r'), ('V', 'oʊ')]; i += 7; continue # hydro-
            if w.startswith('کیمو') and n >= 4:
                toks += [('C', 'k'), ('V', 'iː'), ('C', 'm'), ('V', 'oʊ')]; i += 4; continue # chemo-
            if w.startswith('مینو') and n >= 4:
                toks += [('C', 'm'), ('V', 'æ'), ('C', 'n'), ('C', 'j'), ('V', 'u')]; i += 4; continue # manu-
            if w.startswith('سائبر') and n >= 5:
                toks += [('C', 's'), ('V', 'ai'), ('C', 'b'), ('V', 'E'), ('C', 'r')]; i += 5; continue # cyber-
            if w.startswith('ٹیلی') and n >= 4:
                toks += [('C', 't'), ('V', 'ɛ'), ('C', 'l'), ('V', 'i')]; i += 4; continue # tele-
            if w.startswith('کرپٹو') and n >= 5:
                toks += [('C', 'k'), ('C', 'r'), ('V', 'I'), ('C', 'p'), ('C', 't'), ('V', 'oʊ')]; i += 5; continue # crypto-
            if w.startswith('نیورو') and n >= 5:
                toks += [('C', 'n'), ('V', 'uː'), ('C', 'r'), ('V', 'oʊ')]; i += 5; continue # neuro-
            if w.startswith('اتھار') and n >= 5:
                toks += [('V', 'a'), ('C', 'θ'), ('V', 'o'), ('C', 'r')]; i += 5; continue # author-
            if w.startswith('ایڈو') and n >= 4:
                toks += [('V', 'æ'), ('C', 'd'), ('C', 'v')]; i += 4; continue # adva- / advi- / advo-
            if w.startswith('گلوب') and n >= 4:
                toks += [('C', 'ɡ'), ('C', 'l'), ('V', 'oʊ'), ('C', 'b')]; i += 4; continue # glob-
            if w.startswith('گرڈ') and n >= 3:
                toks += [('C', 'ɡ'), ('C', 'r'), ('V', 'I'), ('C', 'd')]; i += 3; continue # grid-
            if w.startswith('سرو') and n >= 4:
                toks += [('C', 's'), ('V', 'E'), ('C', 'r'), ('C', 'v')]; i += 3; continue # serv- / surv-
            if w.startswith('ریزرو') and n >= 5:
                toks += [('C', 'r'), ('V', 'I'), ('C', 'z'), ('V', 'E'), ('C', 'r'), ('C', 'v')]; i += 5; continue # reserve-
            if w.startswith('نینو') and n >= 4:
                toks += [('C', 'n'), ('V', 'æ'), ('C', 'n'), ('V', 'oʊ')]; i += 4; continue # nano-
            if w.startswith('سیمی') and n >= 4:
                toks += [('C', 's'), ('V', 'ɛ'), ('C', 'm'), ('V', 'i')]; i += 4; continue # semi-
            if w.startswith('ملٹی') and n >= 4:
                toks += [('C', 'm'), ('V', 'U'), ('C', 'l'), ('C', 't'), ('V', 'i')]; i += 4; continue # multi-
            if w.startswith('انگل') and not w.startswith(('انگلی', 'انگلیا', 'انگلیو', 'انگوٹ')) and n >= 4:
                toks += [('V', 'I'), ('C', 'ŋ'), ('C', 'ɡ'), ('C', 'l'), ('V', 'I'), ('C', 'ʃ')]; i += len(w); continue # english
            if w.startswith('ایویلیو') and n >= 7:
                toks += [('V', 'I'), ('C', 'v'), ('V', 'æ'), ('C', 'l'), ('C', 'j'), ('V', 'uː')]; i += 7; continue # evalu-
            if w.startswith('ڈپلی') and n >= 4:
                toks += [('C', 'd'), ('V', 'uː'), ('C', 'p'), ('C', 'l'), ('V', 'I')]; i += 4; continue # dupli-
            if w.startswith('آٹو') and n >= 4:
                toks += [('V', 'o'), ('C', 't'), ('V', 'oʊ')]; i += 3; continue # auto-
            if w.startswith('فوٹو') and n >= 5:
                toks += [('C', 'f'), ('V', 'oʊ'), ('C', 't'), ('V', 'oʊ')]; i += 4; continue # photo-
            if w.startswith('مونو') and n >= 5:
                toks += [('C', 'm'), ('V', 'a'), ('C', 'n'), ('V', 'oʊ')]; i += 4; continue # mono-
            if w.startswith('پولی') and n >= 5:
                toks += [('C', 'p'), ('V', 'a'), ('C', 'l'), ('V', 'i')]; i += 4; continue # poly-
            if w.startswith('پروٹو') and n >= 6:
                toks += [('C', 'p'), ('C', 'r'), ('V', 'oʊ'), ('C', 't'), ('V', 'oʊ')]; i += 5; continue # proto-
            if w.startswith('انفرا') and n >= 6:
                toks += [('V', 'I'), ('C', 'n'), ('C', 'f'), ('C', 'r'), ('V', 'ə')]; i += 5; continue # infra-
            if w.startswith('میگا') and n >= 5:
                toks += [('C', 'm'), ('V', 'ɛ'), ('C', 'ɡ'), ('V', 'ə')]; i += 4; continue # mega-
            if w.startswith('گیگا') and n >= 5:
                toks += [('C', 'ɡ'), ('V', 'I'), ('C', 'ɡ'), ('V', 'ə')]; i += 4; continue # giga-
            if w.startswith('اینٹی') and n >= 5:
                toks += [('V', 'æ'), ('C', 'n'), ('C', 't'), ('V', 'i')]; i += 5; continue # anti-
            if w.startswith('انڈر') and n >= 5:
                toks += [('V', 'U'), ('C', 'n'), ('C', 'd'), ('V', 'E'), ('C', 'r')]; i += 4; continue # under-
            if w.startswith('میکرو') and n >= 5:
                toks += [('C', 'm'), ('V', 'æ'), ('C', 'k'), ('C', 'r'), ('V', 'oʊ')]; i += 5; continue # macro-
            if w.startswith('کرائیو') and n >= 6:
                toks += [('C', 'k'), ('C', 'r'), ('V', 'ai'), ('V', 'oʊ')]; i += 6; continue # cryo-
            if w.startswith('سوشیو') and n >= 6:
                toks += [('C', 's'), ('V', 'oʊ'), ('C', 'ʃ'), ('V', 'i'), ('V', 'oʊ')]; i += 5; continue # socio-
            if w.startswith('یونی') and n >= 5:
                toks += [('C', 'j'), ('V', 'uː'), ('C', 'n'), ('V', 'I')]; i += 4; continue # uni-
        # Medial or standalone work- (-work)
        if (i == 0 or prev_is_v or (toks and toks[-1][0] == 'C')) and w[i:].startswith('ورک') and (i + 3 == n or (i + 3 < n and w[i + 3] in 'سزنگر')):
            toks += [('C', 'w'), ('V', 'E'), ('C', 'r'), ('C', 'k')]; i += 3; continue
        if ch == 'ک' and nxt == 'و' and nxt2 and nxt2 in 'ایے':
            toks += [('C', 'k'), ('C', 'w')]; i += 2; continue   # qu- : سیکوینس, فریکوئینسی
        if ch == 'ا' and i == 0 and nxt == 'س' and nxt2 and nxt2 in 'پٹکمنفلو':
            i += 1; continue                    # prosthetic alif: اسپیکٹرم, اسکول
        if ch == 'ا' and i == 0 and nxt == 'ی' and nxt2 and nxt2 not in VOWEL_LETTERS:
            toks.append(('V', 'a0')); i += 2; continue   # ایکشن, ایپ
        if ch in 'اآ' and nxt == 'ؤ':
            toks.append(('V', 'au')); i += 2; continue          # کلاؤڈ, آؤٹ
        if ch in 'اآ':
            if nxt == 'ئ':                      # ائی / ائ -> aɪ
                toks.append(('V', 'ai')); i += 3 if nxt2 == 'ی' else 2; continue
            if ch == 'آ':
                toks.append(('V', 'A')); i += 1; continue
            toks.append(('V', 'a0' if i == 0 else 'a')); i += 1; continue
        if ch == 'ی' and nxt == 'و' and toks and toks[-1][0] == 'C' and (not nxt2 or nxt2 not in 'ایے'):
            toks.append(('C', 'j')); toks.append(('V', 'u')); i += 2; continue
        if ch == 'ی':
            if i == 0 and nxt in 'اوے':
                toks.append(('C', 'j'))
            elif prev_is_v and toks[-1][1] in ('a', 'A', 'a0') and nxt and nxt not in VOWEL_LETTERS:
                toks.append(('V', 'ai')); toks.pop(-2)   # ا+ی+C : aɪ
            else:
                toks.append(('V', 'i'))
            i += 1; continue
        if ch == 'و':
            if w[i:].startswith('ومبر'):
                toks += [('C', 'v'), ('V', 'E')]; i += 1; continue # نومبر -> noʊvɛmbɚ
            if i == 0:
                toks.append(('C', 'v' if nxt in 'ایے' else 'w'))
            elif prev_is_v and nxt and nxt in 'ایے':
                toks.append(('C', 'v'))             # intervocalic: ریویو, ڈیوائس
            elif prev_is_v and toks[-1][1] in ('u', 'o', 'oʊ'):
                toks.append(('C', 'v'))             # post-vocalic waw: روور -> roʊvɚ
            elif toks and toks[-1] == ('C', 'r') and i > 1 and (i == n - 1 or nxt in 'سزولٹڈکگپبفمن'):
                is_init_cr_cluster = len(w) >= 4 and w[0] in 'کگپٹبفڈ' and w[1] == 'ر' and w[2] == 'و'
                if not is_init_cr_cluster:
                    toks.append(('C', 'v'))         # curve, nerve, marvel, harvest
                else:
                    toks.append(('V', 'u'))
            else:
                toks.append(('V', 'u'))
            i += 1; continue
        if ch == 'ے':
            toks.append(('V', 'e')); i += 1; continue
        if ch in 'ہھ' and i == n - 1 and toks:
            toks.append(('V', 'h')); i += 1; continue
        if ch in 'ئءؤ':
            i += 1; continue
        if ch == 'ع':
            toks.append(('V', 'a')); i += 1; continue
        if ch in CONS:
            toks.append(('C', CONS[ch])); i += 1; continue
        i += 1
    out = []
    for t in toks:
        if t[0] == 'C' and out and out[-1] == t:
            out.append(('V', 'I'))          # سسٹم: identical C C -> C ɪ C
        out.append(t)
    return out


# ---------------------------------------------------------------- cluster repair
def fix_initial(run):
    if legal_onset(run):
        return list(run)
    for o in range(min(3, len(run) - 1), 0, -1):
        if legal_onset(run[-o:]):
            return fix_initial(run[:-o]) + ['E'] + run[-o:]
    return [run[0]] + ['E'] + fix_initial(run[1:])


def fix_final(run):
    if legal_coda(run):
        return list(run)
    # syllabic sonorant: ...C.CCəm / ...təl / ...trəm  (peel the last m n l r)
    if len(run) >= 2 and run[-1] in ('m', 'n', 'l', 'r'):
        coda, onset, rest = fix_medial(run[:-1])
        if rest is None:
            return list(coda) + list(onset) + ['E', run[-1]]
    for k in range(min(3, len(run) - 1), 0, -1):
        if legal_coda(run[:k]):
            return run[:k] + ['E'] + fix_final(run[k:])
    return [run[0], 'E'] + fix_final(run[1:])


def fix_medial(run):
    """returns (coda, onset, extra) where extra is a list of ['E'...] repairs"""
    if len(run) <= 1:
        return [], list(run), None
    for o in range(min(3, len(run)), 0, -1):
        onset, coda = run[-o:], run[:-o]
        if legal_onset(onset) and legal_coda(coda):
            return coda, onset, None
    # repair: keep the longest legal coda, epenthesize, retry on the remainder
    for k in range(min(3, len(run) - 1), 0, -1):
        if legal_coda(run[:k]):
            return run[:k], None, run[k:]
    return run[:1], None, run[1:]


def repair(toks, suffix_follows=False):
    """Return a token list in which every consonant run is legal; 'E' = epenthetic vowel."""
    out, run, seen_v = [], [], False
    for t in toks + [('END', '')]:
        if t[0] == 'C':
            run.append(t[1]); continue
        # flush run
        if run:
            if not seen_v and t[0] == 'V':
                out += [('C', c) if c != 'E' else ('V', 'E') for c in fix_initial(run)]
            elif t[0] == 'END':
                if not seen_v and suffix_follows:
                    parts = fix_initial(run)
                    out += [('C', c) if c != 'E' else ('V', 'E') for c in parts]
                elif not seen_v:           # no vowel letters at all
                    parts = fix_initial(run) if legal_onset(run) else fix_final(run)
                    if 'E' not in parts:
                        parts = [parts[0], 'E'] + parts[1:]
                    out += [('C', c) if c != 'E' else ('V', 'E') for c in parts]
                elif suffix_follows:
                    work = list(run)
                    vowel_suffix = isinstance(suffix_follows, str) and suffix_follows.lstrip('ˈ')[:1] in 'ɪeɑaəɛiouæ'
                    if vowel_suffix and len(work) >= 2 and work[-1] == 'r':
                        # ...Cr + vowel-initial suffix = -er/-or:  مانیٹر+نگ -> mɑːnɪtərɪŋ
                        coda, onset, rest = fix_medial(work[:-1])
                        if rest is None:
                            out += [('C', c) for c in coda] + [('C', c) for c in onset] + [('V', 'E'), ('C', 'r')]
                            work = []
                    while work:
                        coda, onset, rest = fix_medial(work)
                        if rest is None:
                            out += [('C', c) for c in coda] + [('C', c) for c in onset]
                            break
                        out += [('C', c) for c in coda] + [('V', 'E')]
                        work = rest
                else:
                    out += [('C', c) if c != 'E' else ('V', 'E') for c in fix_final(run)]
            else:
                work = list(run)
                while True:
                    coda, onset, rest = fix_medial(work)
                    if rest is None:
                        out += [('C', c) for c in coda]
                        out += [('C', c) for c in onset]
                        break
                    out += [('C', c) for c in coda] + [('V', 'E')]
                    work = rest
            run = []
        if t[0] == 'V':
            out.append(t); seen_v = True
        elif t[0] == 'END':
            break
    return out


# ---------------------------------------------------------------- syllables
def syllabify(toks):
    syl, cur_onset = [], []
    i = 0
    # leading consonants form the first onset
    while i < len(toks) and toks[i][0] == 'C':
        cur_onset.append(toks[i][1]); i += 1
    while i < len(toks):
        key = toks[i][1]; i += 1
        run = []
        while i < len(toks) and toks[i][0] == 'C':
            run.append(toks[i][1]); i += 1
        last = i >= len(toks)
        if last:
            coda, nxt = run, []
        else:
            coda, nxt = [], []
            for o in range(min(3, len(run)), -1, -1):
                onset, c = run[len(run) - o:], run[:len(run) - o]
                if (o == 0 and not run) or (o > 0 and legal_onset(onset) and legal_coda(c)):
                    coda, nxt = c, onset
                    break
            else:
                coda, nxt = run[:1], run[1:]
        syl.append({'onset': cur_onset, 'key': key, 'coda': coda})
        cur_onset = nxt
    return syl


HEAVY_KEYS = {'A', 'ai', 'e', 'au'}


def heavy(s):
    return s['key'] in HEAVY_KEYS or len(s['coda']) >= 2


def assign_stress(syl, rule, has_suffix, suffix_self):
    n = len(syl)
    cand = [k for k, s in enumerate(syl) if s['key'] not in ('E', 'h')] or list(range(len(syl)))
    if suffix_self:
        return None                      # stress sits inside the suffix
    if n == 0 or not cand:
        return None
    if rule == 'prev' and n >= 1:
        k = n - 1 if has_suffix else n - 2
        k = max(0, k)
    elif rule == 'ate':
        k = max(0, n - 2)                # suffix syllable is last; stress antepenult of word
        k = max(0, n - 2) if n <= 2 else n - 2
    else:
        total = n
        if total == 1:
            k = 0
        elif total == 2:
            k = 1 if heavy(syl[1]) else 0
        else:
            k = total - 2 if heavy(syl[total - 2]) else total - 3
    while k not in cand and k > 0:
        k -= 1
    return k if k in cand else cand[0]


# ---------------------------------------------------------------- vowel choice
def vowel(s, stressed, k, syl, word_n, has_suf=False):
    key = s['key']
    closed = len(s['coda']) > 0
    nxt_onset = syl[k + 1]['onset'] if k + 1 < len(syl) else []
    nxt_c = nxt_onset[0] if nxt_onset else ''
    final = k == len(syl) - 1 and not has_suf
    lax_vcv = (not closed) and (not final) and len(nxt_onset) == 1 and word_n >= 3
    if key == 'E':
        if closed and s['coda'] in (['f', 't'], ['s', 't'], ['l', 'm'], ['ŋ', 'k'], ['n', 't']):
            return 'ɪ'
        return 'ɛ' if stressed else 'ə'
    if key == 'h':
        return ''
    if key == 'I':
        return 'ɪ'
    if key == 'au':
        return 'aʊ'
    if key == 'A':
        return 'ɑː'
    if key == 'ai':
        return 'aɪ'
    if key == 'e':
        if closed and s['coda'] == ['m']:
            return 'iː'
        return 'eɪ'
    if key == 'a0':
        return 'æ' if stressed else 'ə'
    if key == 'a':
        if not stressed:
            return 'ə'
        if closed and s['coda'] in (['n', 't'], ['n', 't', 's'], ['n', 's'], ['m', 'p'], ['n']):
            return 'æ'
        if closed and s['coda'] and s['coda'][0] == 'r':
            return 'ɑ'
        return 'ɑː' if not closed else 'ɑː'
    if key == 'uː':
        return 'uː'
    if key == 'iː':
        return 'iː'
    if key == 'æ':
        return 'æ'
    if key == 'ɛ':
        return 'ɛ'
    if key == 'oʊ':
        return 'oʊ'
    if key == 'U':
        return 'ʌ'
    if key == 'i':
        if not stressed:
            return 'i' if final else 'ɪ'
        if closed and s['coda'] in (['n', 'ɡ'], ['n', 'k'], ['n', 's']):
            return 'æ'
        if closed and s['coda'] == ['n', 'tʃ']:
            return 'ɛ'
        if closed and s['coda'] == ['tʃ']:
            return 'iː'
        if closed and s['coda'] in (['s'], ['z'], ['t'], ['m']):
            return 'eɪ'
        if closed or lax_vcv:
            return 'ɛ' if (closed or nxt_c in ('n', 'm', 'l', 'r', 's')) else 'ɪ'
        if k == 0 and word_n >= 2 and nxt_c in STOPS:
            return 'eɪ'
        return 'eɪ' if nxt_c in STOPS else 'iː'
    if key == 'u':
        if not stressed:
            if final:
                return 'oʊ' if s['coda'] else 'uː'
            if k == 1 and syl[0]['key'] == 'ai':
                return 'oʊ'
            return 'ʊ' if (s['coda'][:1] == ['r'] or nxt_c == 'r') else 'ə'
        if closed and s['coda'][0] == 'r':
            if s['onset'] and s['onset'][-1] == 'j':
                return 'ʊ'
            return 'ɔː'
        if closed:
            return 'oʊ' if s['coda'][0] in ('s', 'k', 't', 'p', 'd', 'b', 'ɡ', 'l', 'v') else 'uː'
        if k == 1 and syl[0]['key'] == 'ai':
            return 'oʊ'
        return 'oʊ' if nxt_c in STOPS else 'uː'
    return 'ə'


# ---------------------------------------------------------------- main entry
def english_ipa(word, stress_marks=False):
    w = DIACRITICS.sub('', word.strip())
    # Generative English loan plural handling: -s, -z, -iz
    if len(w) >= 4 and (w.endswith('ز') or (w.endswith('س') and any(w.endswith(x) for x in ('ٹس', 'کس', 'پس', 'فس'))) or w.endswith('یز')):
        if w.endswith('یز') and len(w) >= 4 and w[-3] not in 'ایےاو':
            sing = w[:-1] # keep -y / -ی: باڈیز -> باڈی + z -> bɑdiz
            sing_ipa = english_ipa(sing, stress_marks=stress_marks)
            return sing_ipa + 'z'
        if w.endswith('یز') and len(w) >= 5:
            sing = w[:-2]
            sing_ipa = english_ipa(sing, stress_marks=stress_marks)
            return sing_ipa + ('ɪz' if sing_ipa[-1] in 'szʃʒ' or sing_ipa.endswith(('tʃ', 'dʒ')) else 'z')
        if (w.endswith('ز') or (w.endswith('س') and any(w.endswith(x) for x in ('ٹس', 'کس', 'پس', 'فس')))):
            sing = w[:-1]
            if len(sing) >= 3:
                sing_ipa = english_ipa(sing, stress_marks=stress_marks)
                if sing_ipa[-1] in 'szʃʒ' or sing_ipa.endswith(('tʃ', 'dʒ')):
                    return sing_ipa + 'ɪz'
                elif sing_ipa[-1] in 'ptkfθ':
                    return sing_ipa + 's'
                else:
                    return sing_ipa + 'z'
    stem, suf_ipa, st = split_suffix(w)
    toks = repair(tokenize(stem), suf_ipa)
    # n + k/ɡ -> ŋ (same coda)
    syl = syllabify(toks)
    if not syl:
        # consonant-only stem (e.g. اسٹ + یشن): keep the onset, then the suffix
        head = ''.join(t[1] for t in toks if t[0] == 'C')
        return head + (suf_ipa if stress_marks else suf_ipa.replace('ˈ', ''))
    suffix_self = st == 'self'
    has_suf = bool(suf_ipa)
    k = assign_stress(syl, st, has_suf, suffix_self)
    # an 'ate' suffix is a syllable of its own: stress antepenult of the whole word
    if st == 'ate':
        n_total = len(syl) + 1
        target = n_total - 3
        cand = [i for i, s in enumerate(syl) if s['key'] not in ('E', 'h')] or list(range(len(syl)))
        k = target if target in cand else cand[0]
    n_total = len(syl) + (1 if has_suf else 0)
    qual_k = 0 if (suffix_self and k is None) else k      # stem gets full-vowel (secondary) quality
    out = []
    for i, s in enumerate(syl):
        onset = list(s['onset'])
        coda = list(s['coda'])
        for j in range(len(coda) - 1):
            if coda[j] == 'n' and coda[j + 1] in ('k', 'ɡ'):
                coda[j] = 'ŋ'
        v = vowel(s, i == qual_k, i, syl, n_total, has_suf)
        mark = 'ˈ' if (stress_marks and i == k and k is not None) else ''
        out.append(mark + ''.join(onset) + v + ''.join(coda))
    res = ''.join(out)
    res += suf_ipa if stress_marks else suf_ipa.replace('ˈ', '')
    # General American rhotic and onset phonological repair
    res = re.sub(r'ər(?=[^a-zæɑɔəɛɪiʊuː]|$)', 'ɚ', res)
    res = re.sub(r'ər(?=[b-df-hj-np-tv-z])', 'ɝ', res)
    res = re.sub(r'^ɪ(?=s[ptkbdgmnflw])', '', res)
    res = re.sub(r'iː$', 'i', res)
    res = re.sub(r'ŋɡ$', 'ŋ', res)
    res = re.sub(r'aɪuː$', 'aɪv', res)
    res = res.replace('saːɪb', 'saɪb')
    return res


