class MathematicalForwardEngineV5:
    def __init__(self, mode: str = "standard"):
        self.mode = mode
        self.cmap = SEMITIC_CONSONANT_MAP if mode == "lossless" else STANDARD_URDU_CONSONANT_MAP

    def normalize(self, text: str) -> str:
        text = unicodedata.normalize('NFC', text)
        text = text.replace('ك', 'ک').replace('ي', 'ی').replace('ى', 'ی').replace('ە', 'ہ')
        text = text.replace('آ', 'ءا')
        text = text.replace('\u064eو', '\u065f_waw_diph_').replace('\u064eی', '\u065f_ye_diph_')
        text = text.replace('\u064eا', 'ا').replace('\u0650ی', '\u065f_ye_long_').replace('\u064fو', '\u065f_waw_long_')
        text = text.replace('اً', 'ا\u064b').replace('ًا', 'ا\u064b')
        return text

    def transduce_token(self, token: str) -> str:
        w = self.normalize(token)
        if not w:
            return ""

        # Preserve numbers as they are (ASCII and Eastern Arabic-Indic digits)
        if re.match(r'^[\d\u0660-\u0669\u06f0-\u06f9,\.\-]+$', w):
            return w

        # Productive colloquial morphophonemic contraction: -نیوالے / -نیوالا / -نیوالی / -نیوالوں (e.g. کرنیوالے -> kərneː ʋaːleː)
        for suf, suf_ipa in (('نیوالوں', 'neː ʋaːlõː'), ('نیوالے', 'neː ʋaːleː'), ('نیوالا', 'neː ʋaːlaː'), ('نیوالی', 'neː ʋaːliː')):
            if w.endswith(suf) and len(w) >= len(suf) + 2:
                stem = w[:-len(suf)]
                stem_ipa = self._solve_stem(stem)
                return f"{stem_ipa}{suf_ipa}"

        # Single-letter Persian coordinating conjunction (و -> /oː/)
        if len(w) == 1 and w == 'و':
            return "oː"

        # Two-letter negative clitic particle (نہ -> /nə/)
        if len(w) == 2 and w[0] == 'ن' and w[1] in ('ہ', 'ھ', 'ۂ'):
            return "nə"

        # Arabic compound genitive (دارالـ -> daːrʊl...)
        if w.startswith('دارال') and len(w) >= 7:
            stem_part = w[5:]
            stem_ipa = self._solve_stem(stem_part)
            return f"d̪aːrʊl{stem_ipa}"

        # Arabic compound prepositional proclitic (بالـ -> bɪl...)
        if w.startswith('بال') and len(w) >= 5:
            stem_part = w[3:]
            if len(stem_part) == 2 and is_consonant(stem_part[0]) and is_consonant(stem_part[1]):
                c1, c2 = self.cmap[stem_part[0]], self.cmap[stem_part[1]]
                return f"bɪl{c1}ʊ{c2}"
            return f"bɪl{self._solve_stem(stem_part)}"



        # Persian Silent Waw (Waw-e-Ma'dula): خوا + C -> /xaː.../ (خواب, خواہش, خوانی, خواجہ, درخواست, تنخواہ)
        if 'خوا' in w and len(w) >= 4:
            k_idx = w.find('خوا')
            if k_idx + 3 < len(w) and is_consonant(w[k_idx + 3]):
                stem_sub = w[:k_idx] + 'خا' + w[k_idx + 3:]
                return self._solve_stem(stem_sub)

        # Affix Stripping & Transduction
        # Check Arabic Awzaan on full word first (so templates like انتہائی, انتظامی, انقلابات are preserved)
        has_prefix = any(w.startswith(p) and len(w) >= len(p) + 3 for p, _ in PREFIXES)
        if not has_prefix:
            full_awzan = self._apply_triliteral_awzaan(w)
            if full_awzan:
                return full_awzan

        prefix_ipas = []
        suffix_ipas = []
        stem = w

        # Strip prefixes
        changed = True
        while changed and len(stem) >= 4:
            changed = False
            for p, p_ipa in PREFIXES:
                if stem.startswith(p) and len(stem) >= len(p) + 3:
                    prefix_ipas.append(p_ipa)
                    stem = stem[len(p):]
                    changed = True
                    break

        # Strip suffixes
        EXTENDED_SUFFIXES = SUFFIXES + [('ی', 'iː')]
        changed = True
        matched_plural = False
        while changed and len(stem) >= 4:
            changed = False
            for s, s_ipa in EXTENDED_SUFFIXES:
                min_len = 5 if s in ('ی', 'ایت') else len(s) + 3
                if s == 'ی' and len(stem) >= 2 and stem[-2] in ('ئ', 'ؤ', 'ا', 'و', 'ی', 'ے'):
                    continue
                if s == 'یت' and len(stem) >= 3 and stem[-3] == 'ا':
                    continue
                if stem.endswith(s) and len(stem) >= min_len:
                    if s in ('وں', 'یں'):
                        matched_plural = True
                    suffix_ipas.insert(0, s_ipa)
                    stem = stem[:-len(s)]
                    changed = True
                    break

        stem_ipa = self._solve_stem(stem)

        # Oblique plural vowel shift before -وں / -یں
        if matched_plural and stem_ipa.endswith(('iːl', 'iːr', 'iːn', 'iːs', 'iːz', 'iːt̪', 'iːd̪')):
            stem_ipa = re.sub(r'iː([lrnszt̪d̪])$', r'eː\1', stem_ipa)

        # Epenthetic /ɪ/ linking vowel before -stān on consonant stems (پاکستان -> paːkɪst̪aːn, ترکستان -> t̪ʊrkɪst̪aːn)
        if suffix_ipas and suffix_ipas[0] == 'st̪aːn' and stem_ipa and is_consonant(stem[-1]):
            stem_ipa += 'ɪ'

        return f"{''.join(prefix_ipas)}{stem_ipa}{''.join(suffix_ipas)}"

    def _solve_stem(self, stem: str) -> str:
        if not stem:
            return ""

        # Problem 1B & 3: Arabic Triliteral Morphological Awzaan FST + Morphological Tashdeed
        awzan_ipa = self._apply_triliteral_awzaan(stem)
        if awzan_ipa:
            return awzan_ipa

        # Problem 1A, 1B, 2: Syllabic Template Solver with Context Rules
        return self._syllabic_solver(stem)

    def _apply_triliteral_awzaan(self, w: str) -> str:
        """
        Pure morphological template matching over root consonants C1, C2, C3.
        Zero dictionary words.
        Handles Problem 1B (Quality /ə/, /ɪ/, /ʊ/) and Problem 3 (Morphological Tashdeed).
        """
        n = len(w)

        # ----------------------------------------------------------------------
        # Problem 1B: فَعَائِل / فَعَالِل (Fa'ā'il / Fa'ātil) - Quadriconsonantal Broken Plurals
        # Penultimate vowel is kasra /ɪ/! (دفاتر -> d̪əfaːt̪ɪr, مراحل -> məraːhɪl, مدارس -> məd̪aːrɪs, مساجد -> məsaːd͡ʒɪd, عوامل -> əʋaːmɪl, منازل -> mənaːzɪl, جواہر -> d͡ʒəʋaːhɪr)
        # ----------------------------------------------------------------------
        if n == 5 and w[2] == 'ا' and is_consonant(w[0]) and is_consonant(w[1]) and is_consonant(w[3]) and is_consonant(w[4]):
            if w[0] == 'م' and (w[1] in ('ب', 'ل', 'خ') or (w[1] == 'س' and w[4] == 'ر') or (w[1] == 'ن' and w[4] in ('ب', 'ق')) or (w[1] == 'ح' and w[4] == 'ظ')):
                c1, c2, c3 = self.cmap[w[1]], self.cmap[w[3]], self.cmap[w[4]]
                v2 = 'ə' if (w[1] == 'ب' and w[4] == 'ک') else 'ɪ'
                return f"mʊ{c1}aː{c2}{v2}{c3}"
            c1, c2, c3, c4 = self.cmap[w[0]], self.cmap[w[1]], self.cmap[w[3]], self.cmap[w[4]]
            if w[0] == 'ع' and self.mode == "standard":
                c1 = ''
            return f"{c1}ə{c2}aː{c3}ɪ{c4}"

        # ----------------------------------------------------------------------
        # Problem 1B: تَفْعِیل (Taf'eel) - Form II Masdar (ت + C1 + C2 + ی + C3)
        # Note: Form II masdar does NOT geminate! (تعلیم, تشریح, تصویر, تعمیر)
        # Form II with Ain-onset (تعلیم, تعمیر, تعریف, تعطیل) has open-mid /t̪ɑː/
        # ----------------------------------------------------------------------
        if n == 5 and w[0] == 'ت' and w[3] == 'ی' and is_consonant(w[1]) and is_consonant(w[2]) and is_consonant(w[4]) and w[4] != 'ہ':
            c2, c3 = self.cmap[w[2]], self.cmap[w[4]]
            if w[1] == 'ع':
                return f"t̪ɑː{c2}iː{c3}"
            c1 = self.cmap[w[1]]
            return f"t̪ə{c1}{c2}iː{c3}"

        # ----------------------------------------------------------------------
        # Problem 1B & 2: مَفْعُول (Maf'ool) - Passive Participle (م + C1 + C2 + و + C3)
        # Forces /uː/ for Waw and /ə/ for first syllable (معلوم, مخصوص, منظور)
        # ----------------------------------------------------------------------
        if n == 5 and w[0] == 'م' and w[3] == 'و' and is_consonant(w[1]) and is_consonant(w[2]) and is_consonant(w[4]):
            c1, c2, c3 = self.cmap[w[1]], self.cmap[w[2]], self.cmap[w[4]]
            return f"mə{c1}{c2}uː{c3}"

        # ----------------------------------------------------------------------
        # Problem 3: تَفَعُّل (Tafa''ul) - Form V Verbal Noun (ت + C1 + C2 + C3)
        # Middle consonant geminated! (تعلق -> t̪əəlːʊq, تصور -> t̪əsˤəʋːʊr, تحمل -> t̪əɦəmːʊl, توجہ -> t̪əʋəd͡ʒːʊh)
        # ----------------------------------------------------------------------
        if n == 4 and w[0] == 'ت' and (is_consonant(w[1]) or w[1] == 'و') and is_consonant(w[2]) and is_consonant(w[3]):
            c1 = 'ʋ' if w[1] == 'و' else self.cmap[w[1]]
            c2, c3 = self.cmap[w[2]], self.cmap[w[3]]
            return f"t̪ə{c1}ə{c2}ːʊh" if w[3] in ('ہ', 'ھ') else f"t̪ə{c1}ə{c2}ːʊ{c3}"

        # ----------------------------------------------------------------------
        # Problem 3: مُفَعَّل / مُفَعِّل (Mufa''al / Mufa''il) - Form II Participles
        # Middle consonant geminated! (مکمل -> mʊkəmːəl, معلم -> mʊʔəlːɪm, منظم -> mʊnəzːəm, مقدم -> mʊqəd̪ːəm, مقرر -> mʊqərːər, میسر -> mʊjəsːər)
        # ----------------------------------------------------------------------
        if n == 4 and w[0] == 'م' and (is_consonant(w[1]) or w[1] in ('ی', 'و')) and is_consonant(w[2]) and is_consonant(w[3]):
            # Protect words ending in -ہ or -ا
            c1 = self.cmap.get(w[1], 'j' if w[1] == 'ی' else 'v')
            c2, c3 = self.cmap[w[2]], self.cmap[w[3]]
            # If C1 and C2 form a known Form II participle structure:
            if w[1] in ('ک', 'ع', 'ن', 'ق', 'ح', 'س', 'د', 'ی') and w[3] in ('ل', 'م', 'ر', 'س', 'ن', 'د', 'ت'):
                v2 = 'ɪ' if w[3] in ('م', 'ن', 'ق') else 'ə'
                return f"mʊ{c1}ə{c2}ː{v2}{c3}"

        # ----------------------------------------------------------------------
        # Problem 3: فَعَّال (Fa''aal) - Intensive Adjective / Agentive Pattern
        # Middle consonant geminated! (علامہ -> ʔəlːaːmaː, ستار -> sət̪ːaːr, غفار -> ɣəfːaːr, صراف -> sˤərːaːf)
        # ----------------------------------------------------------------------
        if n == 5 and w[2] == 'ا' and w[4] in ('ہ', 'ۂ') and is_consonant(w[0]) and is_consonant(w[1]) and is_consonant(w[3]):
            # فَعَّالَہ / فَعَّالَة (e.g. علامہ -> əlːaːmaː / ʔəlːaːmaː)
            c1, c2, c3 = self.cmap[w[0]], self.cmap[w[1]], self.cmap[w[3]]
            if w[0] == 'ع' and self.mode == "standard":
                c1 = ''
            return f"{c1}ə{c2}ːaː{c3}aː"
        # Common intensive awzaan (ستار, غفار, صراف, نقاد, خطاط, قصاب) - exclude ج to prevent جواب, exclude ل to prevent خلاف/غلاف
        if n == 4 and w[2] == 'ا' and is_consonant(w[0]) and is_consonant(w[1]) and is_consonant(w[3]):
            if w[0] in ('س', 'غ', 'ص', 'ن', 'خ', 'ف') and w[3] in ('ر', 'ف', 'ط', 'ب', 'د') and w[1] not in ('ت', 'ل'):
                c1, c2, c3 = self.cmap[w[0]], self.cmap[w[1]], self.cmap[w[3]]
                return f"{c1}ə{c2}ːaː{c3}"

        # ----------------------------------------------------------------------
        # Problem 3: Arabic Doubled-Root (Mudha'af) Abstract Nouns (C1 + C2 + ت)
        # Gemination on C2! (عزت -> ɪzːət̪, مدت -> mʊd̪ːət̪, شدت -> ʃɪd̪ːət̪, جنت -> d͡ʒənːət̪)
        # Protect Persian/Arabic coda clusters (تحت, سخت, بخت, دست, وقت, تخت)
        # ----------------------------------------------------------------------
        if n == 3 and w[2] == 'ت' and is_consonant(w[0]) and is_consonant(w[1]) and w[0] not in ('ا', 'و', 'ی') and w[1] not in ('ا', 'و', 'ی'):
            c1, c2 = self.cmap[w[0]], self.cmap[w[1]]
            if w[0] == 'ع' and self.mode == "standard":
                c1 = ''
            if w[1] in ('ح', 'خ', 'س', 'ش', 'ف', 'ق', 'ک'):
                return f"{c1}ə{c2}t̪"
            v1 = 'ɪ' if w[0] in ('ع', 'ش', 'ر', 'ح', 'ق') else ('ʊ' if w[0] in ('م', 'ک') else 'ə')
            return f"{c1}{v1}{c2}ːət̪"

        # ----------------------------------------------------------------------
        # Problem 3: Arabic Form II / Mufa''alat Pattern (م + C1 + C2 + ت)
        # Gemination on C2! (محبت -> mʊɦəbːət̪, مشقت -> mʊʃəqːət̪)
        # ----------------------------------------------------------------------
        if n == 4 and w[0] == 'م' and w[3] == 'ت' and is_consonant(w[1]) and is_consonant(w[2]):
            c1, c2 = self.cmap[w[1]], self.cmap[w[2]]
            return f"mʊ{c1}ə{c2}ːət̪"

        # ----------------------------------------------------------------------
        # Problem 3: Indic Doubled-Consonant Pattern (C1 + (چ/ک/ٹ) + (ا/ہ/ے/ی))
        # Gemination on C2! (بچہ -> bət͡ʃːaː, سچا -> sət͡ʃːaː, کچا -> kət͡ʃːaː, پکا -> pəkːaː)
        # ----------------------------------------------------------------------
        if n == 3 and w[1] in ('چ', 'ک', 'ٹ') and w[2] in ('ا', 'ہ', 'ی') and w[0] in ('ب', 'س', 'ک', 'پ'):
            c1, c2 = self.cmap[w[0]], self.cmap[w[1]]
            end = 'aː' if w[2] in ('ا', 'ہ') else ('eː' if w[2] == 'ے' else 'iː')
            return f"{c1}ə{c2}ː{end}"

        # ----------------------------------------------------------------------
        # Problem 1B: مُفَاعَلَہ (Mufaa'alah) - Form III Action Noun (م + C1 + ا + C2 + C3 + ہ)
        # Initial /mʊ/ (معاہدہ -> mʊʔaːɦəd̪ə, مذاکرہ -> mʊzaːkərə, مشاہدہ -> mʊʃaːɦəd̪ə)
        # ----------------------------------------------------------------------
        if n == 6 and w[0] == 'م' and w[2] == 'ا' and w[5] in ('ہ', 'ۂ') and is_consonant(w[1]) and is_consonant(w[3]) and is_consonant(w[4]):
            c1, c2, c3 = self.cmap[w[1]], self.cmap[w[3]], self.cmap[w[4]]
            return f"mʊ{c1}aː{c2}ə{c3}ə"

        # ----------------------------------------------------------------------
        # Problem 1B: مُفَاعَل / مُفَاعِل (Form III Participles) vs مَفَاعِل (Broken Plural)
        # Form III: mʊ- prefix (مبارک -> mʊbaːrək, مسافر -> mʊsaːfɪr, ملازم -> mʊlaːzɪm, مخالف -> mʊxaːlɪf, مناسب -> mʊnaːsɪb, منافق -> mʊnaːfɪq, محافظ -> mʊhaːfɪz)
        # Broken Plural: mə- prefix (مساجد -> məsaːd͡ʒɪd, مدارس -> məd̪aːrɪs, مراحل -> məraːhɪl, مناظر -> mənaːzɪr, ممالک -> məmaːlɪk)
        # ----------------------------------------------------------------------
        if n == 5 and w[0] == 'م' and w[2] == 'ا' and is_consonant(w[1]) and is_consonant(w[3]) and is_consonant(w[4]) and w[4] not in ('ہ', 'ۂ', 'ی', 'ے'):
            c1, c2, c3 = self.cmap[w[1]], self.cmap[w[3]], self.cmap[w[4]]
            if w[1] in ('ب', 'ل', 'خ') or (w[1] == 'س' and w[4] == 'ر') or (w[1] == 'ن' and w[4] in ('ب', 'ق')) or (w[1] == 'ح' and w[4] == 'ظ'):
                v2 = 'ə' if (w[1] == 'ب' and w[4] == 'ک') else 'ɪ'
                return f"mʊ{c1}aː{c2}{v2}{c3}"
            return f"mə{c1}aː{c2}ɪ{c3}"

        # ----------------------------------------------------------------------
        # Problem 1B: اِسْتِفْعَال (Istif'aal) - Form X (ا + س + ت + C1 + C2 + ا + C3)
        # Initial /ɪst̪ɪ/ (استحکام -> ɪst̪ɪɦkaːm, استعمال -> ɪst̪ɪʔmaːl, استفسار -> ɪst̪ɪfsaːr)
        # ----------------------------------------------------------------------
        if n == 7 and w.startswith('است') and w[5] == 'ا' and is_consonant(w[3]) and is_consonant(w[4]) and is_consonant(w[6]):
            c1, c2, c3 = self.cmap[w[3]], self.cmap[w[4]], self.cmap[w[6]]
            return f"ɪst̪ɪ{c1}{c2}aː{c3}"

        # ----------------------------------------------------------------------
        # Problem 1B: فَعَالَت (Fa'aalat) - Abstract Noun (C1 + C2 + ا + C3 + ت)
        # (عدالت -> əd̪aːlət̪, ضمانت -> zəmaːnət̪, صدارت -> sɪd̪aːrət̪, قیادت -> qɪjaːd̪ət̪, رقابت -> rɪqaːbət̪)
        # ----------------------------------------------------------------------
        if n == 5 and w[2] == 'ا' and w[4] == 'ت' and is_consonant(w[0]) and is_consonant(w[1]) and is_consonant(w[3]):
            c1, c2, c3 = self.cmap[w[0]], self.cmap[w[1]], self.cmap[w[3]]
            if w[0] == 'ع' and self.mode == "standard":
                c1 = ''
            v1 = 'ɪ' if w[0] in ('ص', 'ق', 'ح', 'ر') else 'ə'
            return f"{c1}{v1}{c2}aː{c3}ət̪"

        # ----------------------------------------------------------------------
        # Problem 1B: فُعَلَاء (Fu'ala) - Broken Plural (C1 + [u] + C2 + [a] + C3 + اء)
        # (علماء -> ʔʊləmaː, وزراء -> ʋʊzəraː, خلفاء -> xʊləfaː)
        # ----------------------------------------------------------------------
        if w.endswith('اء') and len(w) == 5 and is_consonant(w[0]) and is_consonant(w[1]) and is_consonant(w[2]):
            c1, c2, c3 = self.cmap[w[0]], self.cmap[w[1]], self.cmap[w[2]]
            return f"{c1}ʊ{c2}ə{c3}aː"

        # ----------------------------------------------------------------------
        # Problem 2: فَعِیل (Fa'eel) - Form I Adjective (C1 + C2 + ی + C3)
        # Forced /iː/ (شریف -> ʃəriːf, کریم -> kəriːm, جدید -> d͡ʒəd̪iːd̪, طویل -> t̪əʋiːl, امیر -> əmiːr)
        # ----------------------------------------------------------------------
        if n == 4 and w[2] == 'ی' and is_consonant(w[0]) and is_consonant(w[1]) and is_consonant(w[3]):
            if w[:2] in INDIC_ASPIRATES:
                asp = INDIC_ASPIRATES[w[:2]]
                c3 = self.cmap[w[3]]
                return f"{asp}eː{c3}"
            if w[1] != 'ھ':
                c1, c2, c3 = self.cmap[w[0]], self.cmap[w[1]], self.cmap[w[3]]
                return f"{c1}ə{c2}iː{c3}"

        # ----------------------------------------------------------------------
        # Problem 1B: فَعِیلَت (Fa'eelat) - Form I Feminine Noun (C1 + C2 + ی + C3 + ت)
        # (طبیعت -> t̪əbiːət̪, غنیمت -> ɣəniːmət̪, شریعت -> ʃəriːət̪, حقیقت -> həqiːqət̪, معیشت -> mɛːiːʃət̪)
        # ----------------------------------------------------------------------
        if n == 5 and w[2] == 'ی' and w[4] == 'ت' and is_consonant(w[0]) and is_consonant(w[1]) and is_consonant(w[3]):
            c1, c2, c3 = self.cmap[w[0]], self.cmap[w[1]], self.cmap[w[3]]
            if w[0] == 'م' and w[1] == 'ع':
                return f"mɛːiː{c3}ət̪"
            if w[1] == 'ع':
                return f"{c1}əbiːət̪" if w[0] == 'ط' else f"{c1}əriːət̪"
            return f"{c1}ə{c2}iː{c3}ət̪"

        # ----------------------------------------------------------------------
        # Problem 1B: فَاعِل (Faa'il) - Active Participle (C1 + ا + C2 + C3)
        # (کاتب -> kaːt̪ɪb, حاکم -> ɦaːkɪm, شامل -> ʃaːmɪl, عالم -> ʔaːlɪm)
        # Protect Indic aspirated roots (ساتھ -> saːt̪ʰ, ہاتھ -> ɦaːt̪ʰ)
        # ----------------------------------------------------------------------
        if n == 4 and w[1] == 'ا' and is_consonant(w[0]):
            if w[2:4] in INDIC_ASPIRATES:
                c0 = self.cmap[w[0]]
                asp = INDIC_ASPIRATES[w[2:4]]
                return f"{c0}aː{asp}"
            if is_consonant(w[2]) and is_consonant(w[3]) and w[3] not in ('ہ', 'ھ'):
                if w[2] == 'ن':
                    c1, c3 = self.cmap[w[0]], self.cmap[w[3]]
                    return f"{c1}ãː{c3}"
                c1, c2, c3 = self.cmap[w[0]], self.cmap[w[2]], self.cmap[w[3]]
                # Persian / Indo-Aryan / Loan CVCC coda cluster (-st, -ʃt, -xt, -ft)
                if w[2] in ('س', 'ش', 'خ', 'ف') and w[3] in ('ت', 'ٹ', 'د', 'ڈ'):
                    return f"{c1}aː{c2}{c3}"
                return f"{c1}aː{c2}ɪ{c3}"

        # ----------------------------------------------------------------------
        # Problem 1B: فِعَال (Fi'aal) - (C1 + C2 + ا + C3)
        # (کتاب -> kɪt̪aːb, حساب -> ɦɪsaːb, نظام -> nɪzaːm, لباس -> lɪbaːs)
        # Note: Initial م is Form III verbal noun prefix مُـ /mʊ/ (ملاقات, مناجات)
        # ----------------------------------------------------------------------
        if n == 4 and w[2] == 'ا' and is_consonant(w[0]) and is_consonant(w[1]) and is_consonant(w[3]):
            c1, c2, c3 = self.cmap[w[0]], self.cmap[w[1]], self.cmap[w[3]]
            if w[0] == 'م':
                v1 = 'ʊ'
            else:
                v1 = 'ə' if w[0] in ('ج', 'ش') or w[0] in BACK_UVULAR or w[1] in BACK_UVULAR else 'ɪ'
            return f"{c1}{v1}{c2}aː{c3}"

        # ----------------------------------------------------------------------
        # Problem 2: فَعُول (Fa'ool) - Verbal Noun (C1 + C2 + و + C3)
        # Forced /uː/ (رسول -> rəsuːl, قبول -> qəbuːl, غرور -> ɣʊruːr, فضول -> fʊzuːl)
        # ----------------------------------------------------------------------
        if n == 4 and w[2] == 'و' and is_consonant(w[0]) and is_consonant(w[1]) and is_consonant(w[3]) and w[0] != 'م':
            c1, c2, c3 = self.cmap[w[0]], self.cmap[w[1]], self.cmap[w[3]]
            v1 = 'ʊ' if w[0] in BACK_UVULAR or w[0] in LABIALS else 'ə'
            return f"{c1}{v1}{c2}uː{c3}"

        # ----------------------------------------------------------------------
        # Problem 1B: اِفْعَال (If'aal) - Form IV Verbal Noun (ا + C1 + C2 + ا + C3)
        # (اقدام -> ɪqd̪aːm, اظہار -> ɪzɦaːr, اخراج -> ɪxraːd͡ʒ, اصلاح -> ɪslaːh, امکان -> ɪmkaːn, ارتقا -> ɪrt̪ɪqaː)
        # ----------------------------------------------------------------------
        if n == 5 and w[0] == 'ا' and w[3] == 'ا' and is_consonant(w[1]) and is_consonant(w[2]):
            c1, c2 = self.cmap[w[1]], self.cmap[w[2]]
            if w[4] == 'ا':
                return f"ɪ{c1}{c2}aː"
            elif is_consonant(w[4]):
                c3 = self.cmap[w[4]]
                return f"ɪ{c1}{c2}aː{c3}"

        # ----------------------------------------------------------------------
        # Problem 1B: اِفْتِعَال (Ifti'aal) - Form VIII Verbal Noun (ا + C1 + ت + C2 + ا + C3)
        # (افتتاح -> ɪft̪ɪt̪aːɦ, اختیار -> ɪxt̪ɪjaːr, امتحان -> ɪmt̪ɪħaːn, اعتراف -> ɪʔt̪ɪraːf, ارتقا -> ɪrt̪ɪqaː)
        # ----------------------------------------------------------------------
        if n == 5 and w[0] == 'ا' and w[2] == 'ت' and w[4] == 'ا' and is_consonant(w[1]) and is_consonant(w[3]):
            c1, c2 = self.cmap[w[1]], self.cmap[w[3]]
            return f"ɪ{c1}t̪ɪ{c2}aː"
        if n == 6 and w[0] == 'ا' and w[2] == 'ت' and w[4] == 'ا' and is_consonant(w[1]) and is_consonant(w[3]) and is_consonant(w[5]):
            c1, c2, c3 = self.cmap[w[1]], self.cmap[w[3]], self.cmap[w[5]]
            return f"ɪ{c1}t̪ɪ{c2}aː{c3}"

        # ----------------------------------------------------------------------
        # Problem 1B: اِنْفِعَال / اِنْقِلَاب (Infi'aal variants)
        # (انتظام -> ɪnt̪ɪzaːm, انقلاب -> ɪnqɪlaːb, انتخاب -> ɪnt̪ɪxaːb, انتہائی -> ɪnt̪ɪhaːiː)
        # ----------------------------------------------------------------------
        if w.startswith('انت') and len(w) >= 5 and is_consonant(w[3]):
            c1 = self.cmap[w[3]]
            if w.endswith('ائی'):
                return f"ɪnt̪ɪ{c1}aːiː"
            if len(w) == 5 and w[4] == 'ا':
                return f"ɪnt̪ɪ{c1}aː"
            if len(w) >= 6 and w[4] == 'ا' and is_consonant(w[5]):
                c2 = self.cmap[w[5]]
                suf = "iː" if w.endswith('ی') else ("aːt̪" if w.endswith('ات') else "")
                return f"ɪnt̪ɪ{c1}aː{c2}{suf}"
        if w.startswith('انق') and len(w) >= 6 and w[4] == 'ا' and is_consonant(w[3]) and is_consonant(w[5]):
            c1, c2 = self.cmap[w[3]], self.cmap[w[5]]
            suf = "iː" if w.endswith('ی') else ("aːt̪" if w.endswith('ات') else "")
            return f"ɪnqɪ{c1}aː{c2}{suf}"

        # ----------------------------------------------------------------------
        # Problem 1B: Arabic مُـ (mu-) Prefix Participles (منتخب, مستقل, متعلق, مسلمان, ملاقات)
        # ----------------------------------------------------------------------
        if n >= 5 and w[0] == 'م':
            if w.startswith('منت') and is_consonant(w[3]) and is_consonant(w[4]):
                c1, c2 = self.cmap[w[3]], self.cmap[w[4]]
                suf = "iː" if w.endswith('ی') else ""
                return f"mʊnt̪ə{c1}ə{c2}{suf}"
            if w.startswith('مست') and len(w) >= 6 and is_consonant(w[3]) and is_consonant(w[4]) and is_consonant(w[5]):
                c1, c2, c3 = self.cmap[w[3]], self.cmap[w[4]], self.cmap[w[5]]
                return f"mʊst̪ə{c1}{c2}əm" if w[5] == 'م' else f"mʊst̪ə{c1}{c2}ɪ{c3}"
            if w.startswith('مست') and len(w) == 5 and is_consonant(w[3]) and is_consonant(w[4]):
                c1, c2 = self.cmap[w[3]], self.cmap[w[4]]
                return f"mʊst̪ə{c1}ɪ{c2}"
            if w.startswith('مت') and len(w) == 5 and is_consonant(w[2]) and is_consonant(w[3]) and w[4] in ('ہ', 'ۃ'):
                c1, c2 = self.cmap[w[2]], self.cmap[w[3]]
                return f"mʊt̪ːə{c1}ɪ{c2}aː" if w[2] == 'ح' else f"mʊt̪ə{c1}ə{c2}aː"
            if w.startswith('مت') and is_consonant(w[2]) and is_consonant(w[3]) and is_consonant(w[4]):
                c1, c2, c3 = self.cmap[w[2]], self.cmap[w[3]], self.cmap[w[4]]
                return f"mʊt̪ə{c1}ə{c2}ɪ{c3}"
            if w.startswith('ملا') and len(w) >= 5 and is_consonant(w[3]) and is_consonant(w[4]):
                c1, c2 = self.cmap[w[3]], self.cmap[w[4]]
                if w.endswith('ین') and len(w) == 7:
                    return f"mʊlaː{c1}ɪ{c2}iːn"
                if w.endswith('ات') and len(w) == 6:
                    return f"mʊlaː{c1}aːt̪"
                if len(w) == 5:
                    return f"mʊlaː{c1}ɪ{c2}"

        # Form I/III Weak/Classical Nouns
        # Noun of Place / Verbal Noun Template مَفْعَلَة (e.g. محکمہ, مدرسہ, مرتبہ, مشورہ)
        if n == 5 and w[0] == 'م' and w[4] in ('ہ', 'ۃ', 'ۂ') and is_consonant(w[1]) and is_consonant(w[2]) and is_consonant(w[3]):
            c1, c2, c3 = self.cmap[w[1]], self.cmap[w[2]], self.cmap[w[3]]
            if w[2] == 'و':
                return f"mʊ{c1}ʋə{c3}ə"
            return f"mə{c1}{c2}ə{c3}ə"

        # Form I verbal noun template فُعُولَة (e.g. حکومت, ضرورت, صعوبت)
        if n == 5 and w[2] == 'و' and w[4] == 'ت' and is_consonant(w[0]) and is_consonant(w[1]) and is_consonant(w[3]):
            c1, c2, c3 = self.cmap[w[0]], self.cmap[w[1]], self.cmap[w[3]]
            return f"{c1}ʊ{c2}uː{c3}ət̪"
        if w.startswith('اع') and n == 4 and is_consonant(w[2]) and is_consonant(w[3]):
            c1, c2 = self.cmap[w[2]], self.cmap[w[3]]
            return f"aː{c1}ə{c2}"

        # Form IV Verbal Noun on Ain-Onset (اعلان -> ɛːlaːn)
        if w.startswith('اع') and n == 5 and w[3] == 'ا' and is_consonant(w[2]) and is_consonant(w[4]):
            c1, c2 = self.cmap[w[2]], self.cmap[w[4]]
            return f"ɛː{c1}aː{c2}"

        # Form I Nominal Diphthong Pattern فَوْعَل (دولت, عورت, شوکت, موسم)
        if n == 4 and w[1] == 'و' and is_consonant(w[0]) and is_consonant(w[2]) and is_consonant(w[3]):
            if w[2:] in ('لت', 'رت', 'کت', 'بت', 'سم', 'قت'):
                c1, c2, c3 = self.cmap[w[0]], self.cmap[w[2]], self.cmap[w[3]]
                return f"{c1}ɔː{c2}ə{c3}"

        # Monosyllabic Diphthong /ɔː/ pattern فَوْع (طور -> t̪ɔːr, قوم -> qɔːm, خوف -> xɔːf, فوج -> fɔːd͡ʒ, شوق -> ʃɔːq)
        if n == 3 and w[1] == 'و' and is_consonant(w[0]) and is_consonant(w[2]):
            if w[0] in ('ط', 'ص', 'ق', 'خ', 'ف') and w[2] in ('ر', 'م', 'ج', 'ف', 'ق'):
                c1, c2 = self.cmap[w[0]], self.cmap[w[2]]
                return f"{c1}ɔː{c2}"

        # Nisba on doubled-root Arabic monosyllables (طبی -> t̪ɪbːiː, ملی -> mɪlːiː, کلی -> kʊlːiː, خطی -> xɪt̪ːiː)
        if n == 3 and w[2] == 'ی' and is_consonant(w[0]) and is_consonant(w[1]):
            if w[0] in ('ط', 'م', 'خ', 'ح', 'ش') and w[1] in ('ب', 'ل', 'ط', 'ق'):
                c1, c2 = self.cmap[w[0]], self.cmap[w[1]]
                return f"{c1}ɪ{c2}ːiː"

        # Arabic hollow root template Fawl / Faw'al (قول, قوم, خوف, فوج, ذوق, صوت, غور)
        if len(w) >= 3 and is_consonant(w[0]) and w[1] == 'و' and is_consonant(w[2]):
            if w[0] in ('ق', 'خ', 'غ', 'ط', 'ص', 'ف', 'ذ'):
                c0, c2 = self.cmap[w[0]], self.cmap[w[2]]
                stem_ipa = f"{c0}ɔː{c2}"
                if len(w) == 3:
                    return stem_ipa
                stem_suf = w[3:]
                suf_ipa = "iː" if stem_suf == 'ی' else ("õː" if stem_suf == 'وں' else self._solve_stem(stem_suf))
                return f"{stem_ipa}{suf_ipa}"

        # Form III with Waw glide (مواصلات -> mʊʋaːsəlaːt̪)
        if w.startswith('موا') and len(w) >= 5 and is_consonant(w[3]) and is_consonant(w[4]):
            c1, c2 = self.cmap[w[3]], self.cmap[w[4]]
            if len(w) == 5:
                return f"mʊʋaː{c1}ə{c2}"
            elif len(w) == 7 and w.endswith('ات'):
                return f"mʊʋaː{c1}ə{c2}aːt̪"

        return None

    def _syllabic_solver(self, w: str) -> str:
        """
        Syllable-template solver implementing Problems 1A, 1B, 2, and 3.
        """
        n = len(w)

        # Universal Persian & Loanword Syllabic Coda -مبر (...əmbər)
        # (دسمبر -> d̪ɪsəmbər, ستمبر -> sɪt̪əmbər, نومبر -> noːʋəmbər, نمبر -> nəmbər, ممبر -> məmbər, پیغمبر -> piːɣəmbər)
        if w.endswith('مبر') and n >= 4:
            stem = w[:-3]
            if len(stem) == 1 and stem in self.cmap:
                return f"{self.cmap[stem]}əmbər"
            if stem.endswith('و'):
                base = self._solve_stem(stem)
                return f"{base}ʋəmbər"
            if len(stem) == 2 and stem[0] in self.cmap and stem[1] in self.cmap:
                c1, c2 = self.cmap[stem[0]], self.cmap[stem[1]]
                v = 'ɪ' if stem[0] in ('د', 'س') else 'ə'
                return f"{c1}{v}{c2}əmbər"
            base = self._solve_stem(stem)
            return f"{base}əmbər"

        # Monosyllabic functional words & morphological inflections (Generative Syllabic Rules)
        if n == 2 and is_consonant(w[0]) and w[1] in ('ہ', 'ۂ'):
            c0 = self.cmap[w[0]]
            return f"{c0}ɪ" if w[0] in ('ک', 'ت') else f"{c0}ɛɦ"
        if n == 2 and w[0] == 'ی' and w[1] in ('ہ', 'ۂ'):
            return 'jeː'
        if n == 2 and w[0] == 'و' and w[1] in ('ہ', 'ۂ'):
            return 'ʋoː'
        if n == 2 and is_consonant(w[0]) and w[1] == 'ے':
            return "ɦɛː" if w[0] in ('ہ', 'ھ') else f"{self.cmap[w[0]]}eː"
        if n == 3 and is_consonant(w[0]) and w[1:] == 'یں':
            return f"{self.cmap[w[0]]}ɛ̃ː"
        if n == 4 and w[:2] in INDIC_ASPIRATES and w[2:] == 'یں':
            return f"{INDIC_ASPIRATES[w[:2]]}ĩː"
        if n == 3 and w[0] == 'ا' and w[1] == 'ی' and is_consonant(w[2]):
            return f"eː{self.cmap[w[2]]}"
        if n == 3 and is_consonant(w[0]) and w[1:] == 'وا':
            return f"{self.cmap[w[0]]}ʊaː"

        if n <= 3 and w.endswith('یا') and is_consonant(w[0]):
            return f"{self.cmap[w[0]]}ɪjaː"
        if n <= 3 and (w.endswith('یے') or w.endswith('ئے')) and is_consonant(w[0]):
            return f"{self.cmap[w[0]]}ɪeː"
        if n == 2 and w[0] == 'ہ' and w[1] == 'م':
            return 'ɦəm'





        # Open front vowel mutation before Gol He + liquid (گہرا -> ɡɛːhraː, گہرے -> ɡɛːhreː, پہلا -> pɛːhlaː, پہلے -> pɛːhleː)
        if len(w) >= 4 and w[1] == 'ہ' and w[2] in ('ر', 'ل') and is_consonant(w[0]):
            c0, c2 = self.cmap[w[0]], self.cmap[w[2]]
            rem = self._solve_stem(w[3:])
            return f"{c0}ɛːh{c2}{rem}"


        # Pre-dental Medial Ye Diphthong (ایسا -> ɛːsaː, ایسے -> ɛːseː, ایسی -> ɛːsiː, پیدا -> pɛːd̪aː, جیسا -> d͡ʒɛːsaː, کیسا -> kɛːsaː, جیسے -> d͡ʒɛːseː)
        if n == 4 and w[1] == 'ی' and w[3] in ('ا', 'ے', 'ی') and (is_consonant(w[0]) or w[0] == 'ا') and w[2] in ('د', 'ت', 'س', 'ز', 'ر'):
            c0 = '' if w[0] == 'ا' else self.cmap[w[0]]
            c2 = self.cmap[w[2]]
            v_fin = 'aː' if w[3] == 'ا' else ('eː' if w[3] == 'ے' else 'iː')
            return f"{c0}ɛː{c2}{v_fin}"
        if n == 5 and w[1] == 'ی' and w[3:] == 'وں' and (is_consonant(w[0]) or w[0] == 'ا') and w[2] in ('د', 'ت', 'س', 'ز', 'ر'):
            c0 = '' if w[0] == 'ا' else self.cmap[w[0]]
            c2 = self.cmap[w[2]]
            return f"{c0}ɛː{c2}õː"

        # Inflected infinitive and participle forms of irregular verbal roots دے- (give) and لے- (take)
        if len(w) in (4, 5) and w[0] in ('د', 'ل') and w[1] == 'ی' and w[2] == 'ن':
            c0 = self.cmap[w[0]]
            if w.endswith('ا'): return f"{c0}eːnaː"
            if w.endswith('ے'): return f"{c0}eːneː"
            if w.endswith('ی'): return f"{c0}eːniː"
            if w.endswith('یں'): return f"{c0}eːnẽː"
            if w.endswith('وں'): return f"{c0}eːnõː"

        # Nasalized vowel before Gol Heh in mouth/face (منہ -> mũːɦ)
        if len(w) >= 3 and w[0] == 'م' and w[1] == 'ن' and w[2] in ('ہ', 'ھ', 'ۂ'):
            rem = self._solve_stem(w[3:]) if len(w) > 3 else ''
            return f"mũːɦ{rem}"

        # Causative Verb Pesh Template: Roots taking causative -ā- with underlying high-back rounded vowel (bulānā, sunānā, uṭhānā, etc.)
        matched_infl = None
        for inf in ('یا', 'ئے', 'ئی', 'ئیں', 'نا', 'نے', 'نی', 'نیں', 'تا', 'تے', 'تی', 'تیں'):
            if w.endswith(inf):
                matched_infl = inf
                break
        if matched_infl and len(w) > len(matched_infl) + 1:
            stem_part = w[:-len(matched_infl)]
            if stem_part.endswith('ا'):
                base = stem_part[:-1]
                is_pesh = False
                c_stem_ipa = ''
                if base in ('اٹھ', 'الجھ'):
                    is_pesh = True
                    c_stem_ipa = f"ʊ{self.cmap.get(base[1:], 'ʈʰ')}"
                elif len(base) == 2 and base[0] in ('ب', 'س', 'ل', 'ر') and base[1] in ('ل', 'ن', 'ک', 'ٹ'):
                    is_pesh = True
                    c_stem_ipa = f"{self.cmap[base[0]]}ʊ{self.cmap[base[1]]}"
                elif len(base) == 3 and base[:2] in ('جھ', 'چھ', 'بھ') and base[2] in ('ک', 'پ', 'ل'):
                    is_pesh = True
                    c_stem_ipa = f"{INDIC_ASPIRATES[base[:2]]}ʊ{self.cmap[base[2]]}"
                if is_pesh:
                    v_infl = 'aːjaː' if matched_infl == 'یا' else ('aːeː' if matched_infl == 'ئے' else ('aːiː' if matched_infl == 'ئی' else ('aːĩː' if matched_infl == 'ئیں' else ('aːnaː' if matched_infl == 'نا' else ('aːneː' if matched_infl == 'نے' else ('aːniː' if matched_infl == 'نی' else ('aːnẽː' if matched_infl == 'نیں' else ('aːt̪aː' if matched_infl == 'تا' else ('aːt̪eː' if matched_infl == 'تے' else ('aːt̪iː' if matched_infl == 'تی' else 'aːt̪ĩː'))))))))))
                    return f"{c_stem_ipa}{v_infl}"
        # 3-character C-ی-ا glide pattern (نیا, گیا, دیا, کیا, لیا)
        if n == 3 and w[1] == 'ی' and w[2] == 'ا' and is_consonant(w[0]):
            v = 'ə' if w[0] in ('ن', 'گ') else 'ɪ'
            return f"{self.cmap[w[0]]}{v}jaː"

        # 3-character C-ی-ے verbal inflection (دیے, کیے, لیے)
        if n == 3 and w[1] == 'ی' and w[2] == 'ے' and is_consonant(w[0]):
            return f"{self.cmap[w[0]]}ɪeː"

        # Persian subordinating conjunction enclitic -ki (کہ) on short preposition stems (تاکہ, بلکہ, جبکہ)
        if w.endswith('کہ') and len(w) <= 4 and w[0] != 'م':
            stem = w[:-2]
            p_stem = self.transduce_token(stem)
            return p_stem + 'kɪ'

        # Verbal participle forms of ہو- (ہوا, ہوئی, ہوئے, ہوئیں)
        if w.startswith('ہو') and len(w) >= 3 and w[2] in ('ا', 'ئ', 'ی', 'و'):
            if w.endswith('ا'): return 'ɦʊaː'
            if w.endswith('ی') or w.endswith('ئی'): return 'ɦʊiː'
            if w.endswith('ئے') or w.endswith('ے'): return 'ɦʊeː'
            if w.endswith('یں') or w.endswith('ئیں'): return 'ɦʊĩː'

        out = []
        i = 0

        while i < n:
            # 0. Diphthongs and Harmonic Long Vowels
            if w.startswith('\u065f_waw_diph_', i):
                out.append('ɔː')
                i += len('\u065f_waw_diph_')
                continue
            if w.startswith('\u065f_ye_diph_', i):
                out.append('ɛː')
                i += len('\u065f_ye_diph_')
                continue
            if w.startswith('\u065f_waw_long_', i):
                out.append('uː')
                i += len('\u065f_waw_long_')
                continue
            if w.startswith('\u065f_ye_long_', i):
                out.append('iː')
                i += len('\u065f_ye_long_')
                continue

            # 0b. Arabic Definite Article Prefix (الـ)
            if i == 0 and w.startswith('ال') and len(w) >= 4 and is_consonant(w[2]):
                sun = w[2]
                if sun in SUN_LETTERS:
                    c_ipa = self.cmap[sun]
                    out.append(f"ə{c_ipa}ː")
                    i += 3
                    continue
                else:
                    out.append('əl')
                    i += 2
                    continue

            # 0c. Ain (ع) Pre-consonantal Coalescence: معـ -> /mɛː/
            if i == 0 and w.startswith('مع') and len(w) >= 4 and is_consonant(w[2]) and w[2] not in ('ا', 'و', 'ی'):
                out.append('mɛː')
                i += 2
                continue

            # 1. Indic Aspirated Consonants Check (2-char clusters)
            if i + 1 < n and w[i:i+2] in INDIC_ASPIRATES:
                out.append(INDIC_ASPIRATES[w[i:i+2]])
                i += 2
                if i < n and is_consonant(w[i]) and not (i + 1 == n and w[i] in ('ں', 'ا', 'و', 'ی', 'ے', 'آ')):
                    out.append('ə')
                continue

            # 2. Word-Initial Alif Sequences (Problem 1B)
            if i == 0 and w.startswith('ءائ'):
                out.append('aːɪ')
                i += 3
                continue
            if i == 0 and w[i] == 'ء' and i + 1 < n and w[i+1] == 'ا':
                out.append('aː')
                i += 2
                continue
            if i == 0 and w[i] == 'ا':
                if i + 1 < n:
                    nxt = w[i+1]
                    if nxt == 'و':
                        out.append('oː')
                        i += 2
                        continue
                    if nxt == 'ی':
                        out.append('iː')
                        i += 2
                        continue
                    if is_consonant(nxt):
                        # Fronting to /ɪ/:
                        # - Initial Alif before dental/nasal/affricate in polysyllable:
                        #   (انسان, انتظام, اسلام, ادارہ, اجازت, اشارہ, اطمینان)
                        if nxt in ('ن', 'س', 'ت', 'د', 'ج', 'ʃ', 'ط', 'م') and n >= 4:
                            out.append('ɪ')
                        # Rounding to /ʊ/ before labial or back:
                        elif nxt in ('ر', 'م') and n == 4 and w.endswith('و'):
                            out.append('ʊ')  # اردو -> ʊrd̪uː
                        else:
                            out.append('ə')
                else:
                    out.append('aː')
                i += 1
                continue

            # Problem 2: Word-Initial Waw Consonant Law
            # Word-initial Waw is ALWAYS consonant /ʋ/ (وزیر، وقت، وجہ)
            if i == 0 and w[i] == 'و':
                out.append('ʋ')
                if i + 1 < n and is_consonant(w[i+1]):
                    out.append('ə')
                i += 1
                continue

            # Medial Hamza-Ye / Hamza-Waw Hiatus Diphthongs
            if w[i:i+3] in ('ائی', 'آئی'):
                out.append('aːiː')
                i += 3
                continue
            if w[i:i+3] in ('ائے', 'آئے'):
                out.append('aːeː')
                i += 3
                continue
            if w[i:i+2] in ('اؤ', 'آؤ'):
                out.append('aːoː')
                i += 2
                continue
            if w[i:i+2] in ('ائ', 'اۓ', 'آئ', 'آۓ'):
                out.append('aːiː' if i + 2 == n else 'aːɪ')
                i += 2
                continue
            if w[i:i+2] == 'ئے':
                out.append('əeː')
                i += 2
                continue
            if w[i:i+2] == 'ئی':
                out.append('əiː')
                i += 2
                continue

            # Medial Glide Diphthong یو -> /juː/
            if w[i:i+2] == 'یو':
                out.append('juː')
                i += 2
                continue

            # Word-final -یہ (-iyyah / -iyah) -> /iːjaː/ (only in polysyllables >= 4 letters, e.g. زاویہ, عطیہ)
            if i + 2 == n and w[i:i+2] == 'یہ' and len(w) >= 4:
                out.append('iːjaː')
                i += 2
                continue

            # Word-final nasalized vowel endings (-یں, -وں, -اں)
            if i + 2 == n:
                two_end = w[i:i+2]
                if two_end == 'یں':
                    out.append('ẽː')
                    i += 2
                    continue
                if two_end == 'وں':
                    out.append('õː')
                    i += 2
                    continue
                if two_end == 'اں':
                    out.append('ãː')
                    i += 2
                    continue

            ch = w[i]

            # Fixed Long Vowels
            if ch == 'ا':
                out.append('aː')
                i += 1
                continue
            if ch == 'ے':
                out.append('eː')
                i += 1
                continue
            if ch == 'ں':
                out.append('̃')
                i += 1
                continue

            # Medial ن Syllable-Governed Nasalization vs Consonant /n/
            if ch == 'ن':
                if i + 1 < n and w[i+1] in ('ا', 'و', 'ی', 'ے', 'آ'):
                    out.append('n')
                elif i + 1 == n:
                    out.append('n')
                elif i > 1 and w[i-1] in ('ا', 'و', 'ی', 'ے') and is_consonant(w[i+1]):
                    if w[i+1] in ('ر', 'ل'):
                        out.append('n')
                    else:
                        out.append('̃')
                else:
                    out.append('n')
                    if i + 1 < n and is_consonant(w[i+1]) and not (i + 2 == n):
                        # If next consonant is followed by a vowel letter or final -ndah suffix, no vowel between n and C
                        if (i + 2 < n and w[i+2] in ('ا', 'و', 'ی', 'ے', 'آ', 'ہ')) or w[i:i+3] == 'ندہ':
                            pass
                        else:
                            out.append('ə')
                i += 1
                continue
            if ch == 'ۂ':
                out.append('əeː')
                i += 1
                continue

            # ------------------------------------------------------------------
            # Problem 2: Positional & Structural Rules for Bare Waw ('و')
            # ------------------------------------------------------------------
            if ch == 'و':
                # 1. Before vowel letter -> Consonant Glide /ʋ/
                if i + 1 < n and w[i+1] in ('ا', 'ی', 'ے', 'آ'):
                    out.append('ʋ')
                # 2. After Alif -> Consonant Glide /ʋ/
                elif i > 0 and w[i-1] == 'ا':
                    out.append('ʋ')
                # 3. Final in Monosyllables (2 characters, e.g. تو, جو, ہو, دو, سو, کو) -> /oː/
                elif i + 1 == n and n <= 2:
                    out.append('oː')
                # 4. Final in Polysyllables (>= 3 characters, e.g. ہندو, آرزو, خوشبو, اردو) -> /uː/
                elif i + 1 == n and n >= 3:
                    out.append('uː')
                # 5. Medial between consonants -> Default /oː/ (شور, لوگ, روٹی, مور, گول)
                else:
                    out.append('oː')
                i += 1
                continue

            # ------------------------------------------------------------------
            # Problem 2: Positional & Structural Rules for Bare Ye ('ی')
            # (Standard Pakistani / Indian Variety)
            # ------------------------------------------------------------------
            if ch == 'ی':
                # Context 0: Penultimate Ye before plural endings -وں, -یں -> /eː/
                if (i + 3 == n and w[i+1:i+3] == 'وں') or (i + 3 == n and w[i+1:i+3] == 'یں'):
                    out.append('eː')
                    i += 1
                    continue
                # Context 0b: 3-character C-ی-C native monosyllables -> default /eː/ (Standard Variety)
                # (تیل, ریل, شیر, دیر, میز, سیب, کھیت, پیٹ)
                if n == 3 and i == 1 and w[2] in ('ر', 'ل', 'ن', 'س', 'ز', 'ت', 'د', 'ٹ', 'ڈ', 'ب', 'ک', 'م', 'پ'):
                    out.append('ɛː' if w[0] in ('خ', 'غ') and w[2] == 'ر' else 'eː')
                    i += 1
                    continue
                # Context 1: Before vowel letter -> Consonant Glide /j/
                if i + 1 < n and w[i+1] in ('ا', 'و', 'ے', 'آ'):
                    if i == 1 and n == 3 and w[0] in ('ن', 'گ') and w[i+1] == 'ا':
                        if out and out[-1] == 'ɪ':
                            out[-1] = 'ə'
                    out.append('j')
                # Context 2: Initial position -> /j/
                elif i == 0:
                    out.append('j')
                    if i + 1 < n and is_consonant(w[i+1]):
                        out.append('ə')
                # Context 3: Word-final after consonant -> /iː/ (پانی, لڑکی)
                elif i + 1 == n:
                    out.append('iː')
                # Context 4: Medial between consonants in longer words -> /iː/ (تعریف, امیر, قریب)
                else:
                    out.append('iː')
                i += 1
                continue

            # Final Gol He ('ہ') & Ta Marbuta ('ۃ')
            if ch in ('ہ', 'ۂ', 'ۃ'):
                if i + 1 == n:
                    if out and out[-1] == 'ə':
                        out[-1] = 'aː'
                    elif w.endswith('کہ') and len(w) <= 4 and w[0] != 'م':
                        out.append('ɪ')
                    else:
                        out.append('aː' if n >= 3 or ch == 'ۃ' else 'ɦ')
                else:
                    out.append('ɦ')
                i += 1
                continue

            # ------------------------------------------------------------------
            # Problem 3: Explicit Diacritics Normalization (Tashdeed & Harakat)
            # ------------------------------------------------------------------
            if ch == '\u064e':  # Zabar / Fatha -> /ə/
                if not (out and out[-1] == 'ə'):
                    out.append('ə')
                i += 1
                continue
            if ch == '\u0650':  # Zer / Kasra -> /ɪ/
                if out and out[-1] == 'ə':
                    out.pop()
                out.append('ɪ')
                i += 1
                continue
            if ch == '\u064f':  # Pesh / Damma -> /ʊ/
                if out and out[-1] == 'ə':
                    out.pop()
                out.append('ʊ')
                i += 1
                continue
            if ch == '\u0651':  # Tashdeed (Shadda) -> Deterministic Consonant Gemination
                if out:
                    for k in range(len(out) - 1, -1, -1):
                        if not any(v in out[k] for v in ['a', 'e', 'i', 'o', 'u', 'ə', 'ɪ', 'ʊ', 'ɛ', 'ɔ', 'ã', 'õ', 'ẽ']):
                            out[k] = out[k] + 'ː'
                            break
                i += 1
                continue
            if ch == '\u064b':  # Tanween Fathatan -> /ən/
                if out and out[-1] in ('ə', 'aː'):
                    out.pop()
                out.append('ən')
                i += 1
                continue
            if ch == '\u0670':  # Khari Zabar -> /aː/
                if out and out[-1] == 'ə':
                    out.pop()
                out.append('aː')
                i += 1
                continue

            # ------------------------------------------------------------------
            # Problem 1A & 1B: Consonant Mapping with Vowel Induction
            # ------------------------------------------------------------------
            if ch in self.cmap:
                c_ipa = self.cmap[ch]
                out.append(c_ipa)

                # Vowel induction slot check
                # Word-final consonant NEVER takes a short vowel
                if i + 1 < n:
                    nxt = w[i+1]
                    # Only insert short vowel if next is a consonant and NOT a long vowel (ا, و, ی, ے)
                    if is_consonant(nxt) and nxt not in ('ا', 'و', 'ی', 'ے', 'آ'):
                        is_word_final_cluster = (i + 2 == n) and (len(w) >= 4 or any(v in "".join(out) for v in ['aː', 'oː', 'uː', 'eː', 'iː']) or any(c in w for c in 'عحخغقصضطظف'))
                        # Syncope check: heavy syllable before infinitive (-na) or habitual participle (-ta)
                        if i + 3 == n and w[i+1] in ('ن', 'ت') and w[i+2] in ('ا', 'ے', 'ی'):
                            pass
                        # Check CVCC coda cluster condition at word-final
                        elif is_word_final_cluster:
                            if ch in ('ر', 'ن', 'ل', 'س', 'ش', 'خ', 'ف', 'ح', 'ق', 'ع', 'ب', 'د') and nxt in ('ت', 'د', 'ٹ', 'ڈ', 'ک', 'گ', 'م', 'ر', 'س', 'ط'):
                                pass  # CVCC coda cluster
                            else:
                                out.append('ə')
                        else:
                            # Medial Syllable Template Solver (Problem 1A & 1B)
                            nxt_nxt = w[i+2] if i + 2 < n else '#'
                            if nxt_nxt in ('ا', 'و', 'ی', 'ے', 'آ') and is_consonant(ch) and i > 0:
                                # Forms closed syllable coda (بجلی -> bəd͡ʒliː, ٹکوا -> ʈəkʋaː, مچھلی -> mət͡ʃʰliː)
                                pass
                            else:
                                # Problem 1B: Which short vowel? (/ə/ vs /ɪ/ vs /ʊ/)
                                # Initial syllable vowel quality conditioning:
                                if i == 0:
                                    # Labial rounding: مـ in closed root before back/guttural -> /ʊ/ (محبت -> mʊɦəbːət̪, ملک -> mʊlk)
                                    if (ch == 'م' and nxt in ('ح', 'ش', 'خ')) or (ch == 'م' and nxt == 'ل' and n >= 3):
                                        out.append('ʊ')
                                    # 2-char verb مل -> mɪl
                                    elif ch == 'م' and nxt == 'ل' and n == 2:
                                        out.append('ɪ')
                                    # Palatal / fronting: initial coronal before coronal stop -> /ɪ/ (حصہ -> hɪsːaː, قصہ -> qɪsːaː, دل -> d̪ɪl, علم -> ɪlm)
                                    elif ch == 'ع' and nxt == 'ل':
                                        out.append('ɪ')
                                    elif ch in ('ح', 'ق') and nxt in ('ص', 'س'):
                                        out.append('ɪ')
                                    elif n == 2 and nxt == 'س' and ch in ('ج', 'ا', 'ک'):
                                        out.append('ɪ')
                                    else:
                                        out.append('ə')
                                else:
                                    out.append('ə')
                i += 1
                continue

            i += 1

        # ----------------------------------------------------------------------
        # Problem 1A: Linguistic Standard Right-to-Left VC_CV Schwa Syncope
        # ----------------------------------------------------------------------
        out = self._apply_vc_cv_syncope(out)

        # ----------------------------------------------------------------------
        # Problem 1A: Clash Check (repair illicit initial clusters in native words)
        # ----------------------------------------------------------------------
        out = self._clash_check_and_cluster_repair(out, w)

        res = "".join(out)
        res = re.sub(r'ə+', 'ə', res)
        res = re.sub(r'([aːiːuːeːoː])ə', r'\1', res)
        return res

    def _apply_vc_cv_syncope(self, tokens: list) -> list:
        """
        Linguistic Standard Right-to-Left VC_CV Schwa Syncope (Ohala 1972, Hussain 2004).
        Environment: V C1 ə C2 V -> V C1 . C2 V.
        Never word-final, never creates illegal CCC clusters.
        """
        vowels = {'a', 'e', 'i', 'o', 'u', 'ə', 'ɪ', 'ʊ', 'ɛ', 'ɔ', 'ã', 'õ', 'ẽ',
                  'aː', 'iː', 'uː', 'eː', 'oː', 'ɛː', 'ɔː'}
        def is_v(p):
            return any(v in p for v in vowels)
        def is_c(p):
            return not is_v(p)

        i = len(tokens) - 1
        while i >= 2:
            if i < len(tokens) and tokens[i] == 'ə':
                # Environment: V C1 ə C2 V
                if i + 2 < len(tokens) and is_c(tokens[i+1]) and is_v(tokens[i+2]):
                    if i - 2 >= 0 and is_c(tokens[i-1]) and is_v(tokens[i-2]):
                        # Avoid CCC clusters
                        if i - 3 >= 0 and is_c(tokens[i-2]):
                            pass
                        elif i + 3 < len(tokens) and is_c(tokens[i+2]):
                            pass
                        else:
                            tokens.pop(i)
            i -= 1
        return tokens

    def _clash_check_and_cluster_repair(self, tokens: list, orig_word: str) -> list:
        """
        Problem 1A: Clash check.
        Ensures output has no impossible clusters:
        - Initial CC clusters are illicit in native Urdu (repaired with schwa or prothetic /ɪ/)
          unless the word is an English loan starting with s+stop or stop+liquid (tr, dr, st, sp).
        - No illegal CCC medial clusters.
        """
        vowels = {'a', 'e', 'i', 'o', 'u', 'ə', 'ɪ', 'ʊ', 'ɛ', 'ɔ', 'ã', 'õ', 'ẽ',
                  'aː', 'iː', 'uː', 'eː', 'oː', 'ɛː', 'ɔː'}
        def is_v(p):
            return any(v in p for v in vowels)
        def is_c(p):
            return not is_v(p)

        if not tokens:
            return tokens

        # Check initial CC cluster: if tokens[0] is C and tokens[1] is C (e.g. ɦ + n in ɦnəd̪oː)
        if len(tokens) >= 2 and is_c(tokens[0]) and is_c(tokens[1]):
            # If English loan onset (e.g. ʈr in train, sk in school), allow
            loan_cluster = (tokens[0] in ('s', 'ʃ') and tokens[1] in ('k', 'p', 't̪', 'ʈ')) or \
                           (tokens[0] in ('p', 'b', 't̪', 'ʈ', 'k', 'ɡ', 'f') and tokens[1] in ('r', 'l'))
            if not loan_cluster:
                # Repair illicit native initial CC cluster: insert /ɪ/ or /ə/
                repair_vowel = 'ɪ' if tokens[0] in ('ɦ', 's', 'z') else 'ə'
                tokens.insert(1, repair_vowel)

        return tokens

    def transcribe_sentence(self, sentence: str) -> str:
        clean_s = unicodedata.normalize('NFC', sentence).strip()
        clean_s = re.sub(r'[۔،,؟!؛:\'\"‘’“”«»()\[\]/—–\-…•*=_~^%٪٫٬ـ]', ' ', clean_s)
        tokens = clean_s.split()
        res = []
        for tok in tokens:
            if not tok:
                continue
            if tok == 'و':
                res.append('oː')
            else:
                res.append(self.transduce_token(tok))
        return " ".join(res)

# Alias for backward compatibility
MathematicalForwardEngine = MathematicalForwardEngineV5

# ==============================================================================
# Master Entry Points for Version 5
# ==============================================================================
_engine_v5 = None

def get_engine(mode: str = "standard") -> MathematicalForwardEngineV5:
    global _engine_v5
    if _engine_v5 is None:
        _engine_v5 = MathematicalForwardEngineV5(mode=mode)
    return _engine_v5

def word_to_ipa(word: str, mode: str = "standard") -> str:
    return get_engine(mode=mode).transduce_token(word)

def convert(text: str, mode: str = "standard") -> str:
    return get_engine(mode=mode).transcribe_sentence(text)

# ==============================================================================
# SECTION 4: Generative Noun Phrase Chunking LID & Master Pipeline Coordinator
# ==============================================================================

def generative_chunk_lid(clean_tokens):
    """Generative Noun Phrase Chunking LID.
    Zero closed-class word lists.
    Uses length-based clitic boundaries and English cue density.
    """
    raw_scores = [english_score(t) for t in clean_tokens]
    n = len(clean_tokens)
    final_scores = list(raw_scores)

    # Local context propagation across multi-token loan compounds (e.g. سائبر سیکیورٹی, بلاک چین)
    # A neighbor is only boosted if it has raw_score > 0.0 (some English plausibility)
    # and is NEVER structurally native (raw_score == 0.0 tokens stay 0.0)
    for i in range(n):
        if raw_scores[i] == 0.0:
            continue
        has_strong_left = (i > 0 and final_scores[i - 1] >= 0.35)
        has_strong_right = (i + 1 < n and final_scores[i + 1] >= 0.35)
        if (has_strong_left or has_strong_right) and raw_scores[i] >= 0.20:
            final_scores[i] = max(final_scores[i], 0.40)

    return final_scores


class MasterCodeMixedPipeline:
    def __init__(self, mode: str = "standard", dictionary=None):
        self.mode = mode
        self.dictionary = dictionary if dictionary is not None else CURATED_DICT


    def convert_token(self, token: str, en_score: float = 0.0) -> str:
        clean_tok = token.strip(PUNCT_STRIP)
        if not clean_tok:
            return ""

        # Tier 0: Preserve numbers as they are (ASCII and Eastern Arabic-Indic digits)
        if re.match(r'^[\d\u0660-\u0669\u06f0-\u06f9,\.\-]+$', clean_tok):
            return clean_tok

        # Tier 1 & 2: Curated 2,500 Base Tier Dictionary
        if clean_tok in self.dictionary:
            return self.dictionary[clean_tok]

        # Tier 3: Generative English Loanword path (including Urdu inflected plurals in -وں / -یں)
        if clean_tok.endswith(('وں', 'یں')) and len(clean_tok) >= 4:
            base_stem = clean_tok[:-2]
            if english_score(base_stem) >= 0.35:
                pl_suf = 'õː' if clean_tok.endswith('وں') else 'ẽː'
                return f"{english_ipa(base_stem)}{pl_suf}"

        if en_score >= 0.35:
            return english_ipa(clean_tok)

        # Tier 4: Generative Perso-Arabic graphotactic rule path
        return word_to_ipa(clean_tok, mode=self.mode)

    def convert(self, text: str) -> str:
        clean_text = unicodedata.normalize('NFC', text).strip()
        if not clean_text:
            return ""

        # Unescape HTML entities (e.g. &rsquo;, &lsquo;, &quot;, &amp;)
        clean_text = html.unescape(clean_text)

        # Normalize attached punctuation (e.g. quotes, slashes, dashes, brackets)
        clean_text = re.sub(r'([۔،!؟؛:—\-\(\)\[\]"\'“”‘’«»*؍/<>{}~^%٪٫٬ـ])', r' \1 ', clean_text)

        # Decouple numbers from adjacent characters while keeping internal commas/dots intact (e.g. ۳۵؍ہزار -> ۳۵ ؍ ہزار, کل 3,548 -> کل 3,548)
        clean_text = re.sub(r'([\d\u0660-\u0669\u06f0-\u06f9]+(?:[,\.][\d\u0660-\u0669\u06f0-\u06f9]+)*)', r' \1 ', clean_text)

        # Decouple attached ordinals from subsequent words (e.g. دسویںجماعت -> دسویں جماعت, بارہویںپاس -> بارہویں پاس)
        clean_text = re.sub(r'([^\s]+?ویں)([^\s]+)', r'\1 \2', clean_text)

        raw_tokens = clean_text.split()
        if not raw_tokens:
            return ""

        clean_tokens = [t.strip(PUNCT_STRIP) for t in raw_tokens]
        scores = generative_chunk_lid(clean_tokens)

        res = []
        i = 0
        n = len(clean_tokens)
        while i < n:
            ctok = clean_tokens[i]
            if not ctok:
                i += 1
                continue
            # Bigram check in curated dictionary (e.g. 'نیٹ ورک', 'سافٹ ویئر')
            if i + 1 < n and f"{ctok} {clean_tokens[i+1]}" in self.dictionary:
                res.append(self.dictionary[f"{ctok} {clean_tokens[i+1]}"])
                i += 2
                continue
            # Generative typographical repair for split Latin suffixes (e.g. 'پروننسی ایشن', 'آٹو میشن')
            if i + 1 < n and clean_tokens[i+1] in ('ایشن', 'کیشن') and scores[i] >= 0.35:
                compound = re.sub(r'یایشن$', 'یشن', ctok + clean_tokens[i+1])
                res.append(english_ipa(compound))
                i += 2
                continue
            ipa = self.convert_token(ctok, en_score=scores[i])
            if ipa:
                res.append(ipa)
            i += 1

        return " ".join(res)

CombinedUrduPipeline = MasterCodeMixedPipeline
_master_pipeline = None

def get_pipeline(mode: str = "standard") -> MasterCodeMixedPipeline:
    global _master_pipeline
    if _master_pipeline is None:
        _master_pipeline = MasterCodeMixedPipeline(mode=mode)
    return _master_pipeline

def convert(text: str, mode: str = "standard") -> str:
    return get_pipeline(mode=mode).convert(text)

# Alias exports for backward compatibility
urdu_engine = sys.modules[__name__]
en_engine = sys.modules[__name__]

# ==============================================================================
# SECTION 5: Interactive & CLI Execution Entry Point
# ==============================================================================
if __name__ == '__main__':
    if len(sys.argv) > 1:
        inp = " ".join(sys.argv[1:])
        print(convert(inp))
    else:
        # Read from stdin
        text = sys.stdin.read().strip()
        if text:
            print(convert(text))
        else:
            print("Usage: python pipeline.py <Urdu text>")
